window.KUATEntrySeed = {"schemaVersion": 1, "entries": [{"id": "entry-c8ef5ebd0116", "title": "塔罗斯", "type": "地点", "aliases": [], "tags": [], "summary": "这个世界是在裂缝之上的世界，永恒帝国沉入复平面时所遗留的巨大裂缝让这个世界永无休止的下雨。", "body": "### 星球概述\n这个世界是在裂缝之上的世界，永恒帝国沉入复平面时所遗留的巨大裂缝让这个世界永无休止的下雨。\r\n\r\n这个星球名为**塔罗斯**。受限于自然环境的恶劣，这里始终无法发展出足以支持民主社会的生产力，但影子之间却有自上而下的团结与自由。\r\n\r\n地磁时常混乱，信号干扰极其强烈。在一些地方，甚至会有常年不散的黑雨，是无法生存甚至无法停留之地。\r\n\r\n这个星球就在裂缝之上，谁也没想到这里会诞生文明，在一切发生之前，这里是无神注视的地方。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "星球概述", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-e756b024777a", "title": "影子一族", "type": "组织", "aliases": [], "tags": [], "summary": "热衷于世界真相并管理国家的一群人，被统称为影子一族。", "body": "### 影子一族\n热衷于世界真相并管理国家的一群人，被统称为**影子一族**。\r\n\r\n国家和影子是共存的状态，政府是帮助影子管理这个国家的机构，暴力机器掌握在影子手中，国家首脑和要员自然大多都是影子。\r\n\r\n他们具有某些先进的技术，或是强大的权力，或是未知的知识。\r\n\r\n影子之间约定：不论影子之间斗得再怎么凶狠，祸不及人民，要保障人民的生活。\r\n\r\n> **命名规范**：所有影子一族的称呼都是\"某某一族\"，而不是\"某某家\"。包括洛星雪称呼自己家的时候也要称呼\"洛星一族\"。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "影子一族", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-f1b2fbe83267", "title": "黑雨", "type": "概念", "aliases": [], "tags": [], "summary": "黑雨是一种具有对人来说强毒素的雨，雨水发黑，触之必死。", "body": "### 黑雨\n黑雨是一种具有对人来说强毒素的雨，雨水发黑，触之必死。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "黑雨", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-5fadbe35c5d0", "title": "异象", "type": "概念", "aliases": [], "tags": [], "summary": "异象是源头为裂缝的异常现象，时常伴随各类裂缝构造体出现。", "body": "### 异象\n异象是源头为裂缝的异常现象，时常伴随各类裂缝构造体出现。\r\n\r\n异象之间常间隔六七年，基本都会伴随巨大灾害，很少有无灾害异象。\r\n\r\n### 裂缝与异象的关系\r\n\r\n裂缝的波动是异象发生的根源。每当裂缝产生剧烈波动，便会在塔罗斯的某处引发异象。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "异象", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-ea163b91e6c6", "title": "构造体", "type": "概念", "aliases": [], "tags": [], "summary": "异象通常产出名为构造体的非生命造物。这些构造体来自裂缝的另一侧，形态各异，但有一个共同特征——它们并非有生命的个体，而是某种功能性的造物。", "body": "### 构造体\n异象通常产出名为**构造体**的非生命造物。这些构造体来自裂缝的另一侧，形态各异，但有一个共同特征——它们并非有生命的个体，而是某种功能性的造物。\r\n\r\n构造体可以用四项能量指标进行测量，正常状态下这四项指标呈现**线性关系**。当能量指标出现异常偏离时，往往意味着异象本身也在发生变化。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "构造体", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-7f004b0366ab", "title": "裂缝", "type": "概念", "aliases": [], "tags": [], "summary": "裂缝的学名为深空裂缝，宇宙中的其他文明称其为深空位面通道。", "body": "### 裂缝\n裂缝的学名为**深空裂缝**，宇宙中的其他文明称其为深空位面通道。\r\n\r\n深空裂缝的长度通常在3AU到10AU之间。像塔罗斯裂缝这种直接包住整个星系的、长度约130AU的巨大裂缝，几乎从未发现过。\r\n\r\n深空裂缝连接本宇宙的实位面与复位面，是复位面外泄的体现。在裂缝的入口处，一切都会沾染非实属性，导致整体的虚化。这一过程使得塔罗斯星系的所有物体都无法完整存在于非裂缝入口处，不然会因为信息缺失自行崩溃。\r\n\r\n裂缝是一个客观存在的东西，没有任何能够基于裂缝研究的技术，只有知识。裂缝的覆盖范围仅限于塔罗斯星系。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "裂缝", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-c9884e418b6f", "title": "实位面与复位面", "type": "概念", "aliases": [], "tags": [], "summary": "在最深层次上，宇宙是数学的。有序的物质世界属于实位面，无序的物质世界属于复位面。实位面和复位面都属于可知域。复位面的外泄指的是虚属性的侵染性外泄，这是裂缝最基本的属性。", "body": "### 实位面与复位面\n在最深层次上，宇宙是数学的。有序的物质世界属于**实位面**，无序的物质世界属于**复位面**。实位面和复位面都属于可知域。复位面的外泄指的是虚属性的侵染性外泄，这是裂缝最基本的属性。\r\n\r\n**实位面与复位面是一切宇宙的基本位面**（类似于基本属性）——凡为宇宙，必有此两面。因此复位面并非某个已毁灭宇宙的残骸，上一轮宇宙同样具备实位面与复位面。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "实位面与复位面", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-8e5dd057dddb", "title": "实属性与复属性", "type": "概念", "aliases": [], "tags": [], "summary": "世界上的所有物体都具有多种不同的属性，大致分为实属性和复属性。实属性需要实位面源源不断地信息支撑，复属性需要复位面源源不断地信息支撑。如果一个物体同时拥有了实属性和复属性，那么这个物体就同时需要两个位面的信息支撑——但除了裂缝以外，没有任何地方能同时提供两个位面的信息。", "body": "### 实属性与复属性\n世界上的所有物体都具有多种不同的属性，大致分为**实属性**和**复属性**。实属性需要实位面源源不断地信息支撑，复属性需要复位面源源不断地信息支撑。如果一个物体同时拥有了实属性和复属性，那么这个物体就同时需要两个位面的信息支撑——但除了裂缝以外，没有任何地方能同时提供两个位面的信息。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "实属性与复属性", "role": "摘录来源"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6f825744d300", "title": "西斯塔常数与西斯塔位面", "type": "概念", "aliases": [], "tags": [], "summary": "时空异位会导致本区域的时空相位数量呈指数级增长，相位差会高速增长。当相位差的绝对值超过西斯塔常数时，该时空相位会抵达世界能承受的相位极值，处于此相位的时空称为西斯塔位面。", "body": "### 西斯塔常数与西斯塔位面\n时空异位会导致本区域的时空相位数量呈指数级增长，相位差会高速增长。当相位差的绝对值超过**西斯塔常数**时，该时空相位会抵达世界能承受的相位极值，处于此相位的时空称为**西斯塔位面**。\r\n\r\n西斯塔位面类似于一个极限——这里本就存在一个相位，但任何其他时空相位都无法正常抵达这里。因为当其他相位抵达西斯塔位面时，世界的承受能力达到上限，随后相位差迅速归零，这片区域的全部时空相位都会被立刻压缩回主位面（即常态相位，也就是实位面——所有时空相位都是附着于实位面上的平行面）。这种速度的压缩会导致复位面发生虚数海啸，并引起实位面上的时空震荡。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "西斯塔常数与西斯塔位面", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-318a6d61b665", "title": "时空异位", "type": "概念", "aliases": [], "tags": [], "summary": "裂缝能够引发一种名为时空异位的现象，指的是多组具有不同相位差的时空发生接触，体现为在这一地区的时空混乱。这被塔罗斯人称为异象。", "body": "### 时空异位\n裂缝能够引发一种名为**时空异位**的现象，指的是多组具有不同相位差的时空发生接触，体现为在这一地区的时空混乱。这被塔罗斯人称为异象。\r\n\r\n异象可能是：大量不属于本相位的物体出现在本相位、时空不稳定导致的空间混乱、本相位和其他相位的物体错误拼接等多种情况。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "时空异位", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-1f70ddefb673", "title": "货币体系", "type": "概念", "aliases": [], "tags": [], "summary": "塔罗斯世界的通用货币单位为诺。这是影子一族主导经济体系下统一发行的货币，在各国、各城邦普遍流通。参考物价：四个鸡蛋灌饼售价约24诺（序章第1章）。", "body": "### 货币体系\n塔罗斯世界的通用货币单位为**诺**。这是影子一族主导经济体系下统一发行的货币，在各国、各城邦普遍流通。参考物价：四个鸡蛋灌饼售价约24诺（序章第1章）。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "货币体系", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-4b848349b6b7", "title": "电子支付系统", "type": "概念", "aliases": [], "tags": [], "summary": "塔罗斯世界存在与魔法文明共存的现代化电子支付手段。尽管世界整体科技发展不均衡，部分大城市已普及扫码支付等便捷手段，与传统的现金（诺）支付并行使用。", "body": "### 电子支付系统\n塔罗斯世界存在与魔法文明共存的现代化电子支付手段。尽管世界整体科技发展不均衡，部分大城市已普及扫码支付等便捷手段，与传统的现金（诺）支付并行使用。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "电子支付系统", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b6c0073fe26c", "title": "天气模拟力场", "type": "概念", "aliases": [], "tags": [], "summary": "天气模拟力场是一种高级科技装置，能在特定区域内模拟出理想天气（隔绝外界的无尽之雨）。按覆盖规模分为：", "body": "### 天气模拟力场\n天气模拟力场是一种高级科技装置，能在特定区域内模拟出理想天气（隔绝外界的无尽之雨）。按覆盖规模分为：\r\n\r\n- **大尺度**：覆盖庄园、学院等大型区域，耗能巨大，技术门槛极高。\r\n- **小尺度**：覆盖学校操场、集市等中小型区域。\r\n\r\n诺斯卡尔高等学院拥有**世界上最大的天气模拟系统**，配备最高效的能源和最优的算法。包括国家财阀在内，外界从未放弃过向学院购买这项技术，但学院始终以天价回绝，**从不售出**。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "天气模拟力场", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-a049419b69e3", "title": "遗迹分类体系", "type": "概念", "aliases": [], "tags": [], "summary": "塔罗斯世界中发现的古代遗迹根据科技等级和文明来源分为两大类：", "body": "### 遗迹分类体系\n塔罗斯世界中发现的古代遗迹根据科技等级和文明来源分为两大类：\r\n\r\n**阿尔法型（Alpha型）：** 较低级别的遗迹，来自前文明时代。按用途又分为五大类：工业型、中心型、农业型、能源型、武器型。\r\n\r\n**贝塔型（Beta型）：** 比阿尔法型遗迹更为高级的存在，来自更古老的未知文明。贝塔型遗迹的特化功能更强，科技跨度远大于阿尔法型，内部常藏有难以理解的技术和知识。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "遗迹分类体系", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-bd2fcbba487d", "title": "应变性设备", "type": "概念", "aliases": [], "tags": [], "summary": "遗迹中发掘出的武器类造物统称为应变性设备。这类武器在不同势力中有不同的称谓——魔导会将其称为\"魔导器\"，教会则将其称为\"神器\"。尽管名称各异，本质上都是古代文明遗留下来的可激活武器系统。", "body": "### 应变性设备\n遗迹中发掘出的武器类造物统称为**应变性设备**。这类武器在不同势力中有不同的称谓——魔导会将其称为**\"魔导器\"**，教会则将其称为**\"神器\"**。尽管名称各异，本质上都是古代文明遗留下来的可激活武器系统。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "应变性设备", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-c01df17a9fde", "title": "月花", "type": "概念", "aliases": [], "tags": [], "summary": "一种奇特的发光花朵，天黑后自然绽开并发出柔和的荧光。在伯斯塔城老城区，可在沿街树梢上看到月花的踪迹（序章第5章）。这种花的存在为塔罗斯的永夜增添了一抹诗意。", "body": "### 月花\n一种奇特的发光花朵，天黑后自然绽开并发出柔和的荧光。在伯斯塔城老城区，可在沿街树梢上看到月花的踪迹（序章第5章）。这种花的存在为塔罗斯的永夜增添了一抹诗意。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "月花", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-223553dbf095", "title": "法阵医疗", "type": "概念", "aliases": [], "tags": [], "summary": "在伯斯塔等大城市，医疗体系呈现科技与魔法的深度融合。以伯斯塔医院为代表，医院中法阵与常规科技医疗仪器并用：传统医疗设备处理物理创伤，而法阵系统则能处理因元素、异象等超自然因素造成的特殊损伤。", "body": "### 法阵医疗\n在伯斯塔等大城市，医疗体系呈现科技与魔法的深度融合。以伯斯塔医院为代表，医院中法阵与常规科技医疗仪器**并用**：传统医疗设备处理物理创伤，而法阵系统则能处理因元素、异象等超自然因素造成的特殊损伤。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "edb0ddf58d45d516", "heading": "法阵医疗", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-dfe9fac81d5b", "title": "前文明时代", "type": "事件", "aliases": [], "tags": [], "summary": "人类逐渐开发宇宙，在一次次的探索中发现了此片空间无法逃出，物质被吸引进入某一处区域。众多科学家研究后发现，他们的星系前方有一片复位面裂缝，地球可能就在这个裂缝的口上，甚至可能就在裂缝之中，地球现在无法逃离。", "body": "### 前文明时代\n人类逐渐开发宇宙，在一次次的探索中发现了此片空间无法逃出，物质被吸引进入某一处区域。众多科学家研究后发现，他们的星系前方有一片复位面裂缝，地球可能就在这个裂缝的口上，甚至可能就在裂缝之中，地球现在无法逃离。\r\n\r\n他们将消息公开于大众后，人类空前的团结，为了离开裂缝，拼尽一切。\r\n\r\n随着对裂缝的深入研究，人类发现了地球上种种异常的原因。但最重要的一点无法解释——那就是不同寻常的雨。根据记载，雨在很久很久以前并不是一刻不停地下着的。\r\n\r\n直到人类发现了名为**时空异位**的现象存在。时空异位是一种灾难，具有极强的不确定性，但一旦出现，在不知道多久的未来，一定会爆发名为**时空异位冲击**的灾难，以无法知晓的方式毁灭一切。\r\n\r\n不幸的是，时空异位冲击的前兆——错位能量涌动和时间乱流——已经出现。时空异位冲击已经不远了。在这个发现公之于众后，很多人逐渐放弃了原来的抵抗准备拥抱死亡，但大多数人选择了坚持。在一段时间后，联合政府正式成立，整个地球团结一体，只为抵抗不公的命运。\r\n\r\n后来的人类将这之后的时代称之为\"大毁灭之前\"。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "前文明时代", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-d2dd3b492926", "title": "大毁灭", "type": "事件", "aliases": [], "tags": [], "summary": "大毁灭指的是前文明联合政府成立到来自裂缝的时空异位冲击结束之间的时期。", "body": "### 大毁灭\n大毁灭指的是前文明联合政府成立到来自裂缝的时空异位冲击结束之间的时期。\r\n\r\n在这期间，人类为了解决时空异位冲击，制定了名为**修正计划**的计划，拼尽一切建立了名为**时空方碑**的装置，想以此修正时空异位。\r\n\r\n但还没等到时空方碑彻底建成，时空异位冲击便提前到来了。没有人知道，这不是因为科学家的计算失误——这场时空异位是宇宙级别的时空异位，无数其他星系也遭受了时空异位。\r\n\r\n远在宇宙另一端的**白羽绫**，察觉到了这名为时空震荡的灾难，并溯源到了多个裂缝。为解决这一灾难，她强行修正了在裂缝之外的时空异位，造成了时空震荡的提前爆发。\r\n\r\n不巧的是，人类所在星系的一半在裂缝之中，一半在裂缝之外。这个星系真的就堵在了复位面到实位面的过渡裂缝上。于是，大毁灭发生了——人类被时空震荡彻底毁灭。震荡带来的时空异位把多个依附于实位面的平行面上的人类建筑拽到了实位面上。\r\n\r\n同时，在填补裂缝的时候，白羽绫注意到了这个星球上的文明，决定留下来，监视这里。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "大毁灭", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-ee8c844b4dad", "title": "时空震荡", "type": "事件", "aliases": [], "tags": [], "summary": "时空震荡是超高强度的时空异位，会将附着在实位面上的平行面强行压进实位面，并且将压缩后的重复部分随机删除。同时复位面上会掀起虚数海啸，震荡程度与海啸高度相等。震荡越剧烈，越可能会引起复位面上浮至实位面。", "body": "### 时空震荡\n时空震荡是超高强度的时空异位，会将附着在实位面上的平行面强行压进实位面，并且将压缩后的重复部分随机删除。同时复位面上会掀起虚数海啸，震荡程度与海啸高度相等。震荡越剧烈，越可能会引起复位面上浮至实位面。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "时空震荡", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-f01d1eaee029", "title": "帝国回归", "type": "事件", "aliases": [], "tags": [], "summary": "时空震荡本不常见，但由于帝国一直在尝试回归，造成了裂缝越来越大、越来越多。现在，最大的裂缝就是塔罗斯星系所在的裂缝。帝国已经注意到了这里，只要成功让星碑启动，帝国将回归实位面。", "body": "### 帝国回归\n时空震荡本不常见，但由于帝国一直在尝试回归，造成了裂缝越来越大、越来越多。现在，最大的裂缝就是塔罗斯星系所在的裂缝。帝国已经注意到了这里，只要成功让星碑启动，帝国将回归实位面。\r\n\r\n---", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "帝国回归", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-2b5adab18a72", "title": "诺斯卡尔高等学院创立", "type": "事件", "aliases": [], "tags": [], "summary": "学院创立之前，世界上影子一族之间的矛盾已经几乎到了不可调和的地步。只是受限于影子一族统治地区之间的间隔环境极为恶劣，战争才没有打起来——但也就差一点了。政治上，教会已经压不住局面，圣殿骑士团已经整装待发，随时准备武力调节。", "body": "### 诺斯卡尔高等学院创立\n学院创立之前，世界上影子一族之间的矛盾已经几乎到了**不可调和**的地步。只是受限于影子一族统治地区之间的间隔环境极为恶劣，战争才没有打起来——但也就差一点了。政治上，**教会已经压不住局面**，**圣殿骑士团**已经整装待发，随时准备武力调节。\r\n\r\n就在这个时候，**伊瑟尔**来了。她对所有影子一族和各类组织的首脑宣称：自己要统一所有教学资源，创立世界上最大的高等学院。\r\n\r\n**斯卡利一族**——当时几乎最强大的影子一族——等比较强大的影子一族自然不同意。教会**得到神谕，不发表任何态度**。\r\n\r\n结果：这些反对的影子一族，在**发表反对声明的当晚**被伊瑟尔**全族抹除**。\r\n\r\n伊瑟尔建院之初用的是**纯粹的武力**——以她的实力，当时几乎不需要有任何遇到强敌的顾虑。而她之所以更侧重于用学院去布局，是因为她的最终目的是**解决裂缝这个麻烦、保住塔罗斯这个世界**；她认为这是绫会希望自己成为的样子。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "诺斯卡尔高等学院创立", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-753dbced3c27", "title": "海德纳事件", "type": "事件", "aliases": [], "tags": [], "summary": "五年前，一场毁灭性的裂缝异象灾难降临海德纳领地。异象爆发时，天空被染成血红色，大量构造体从裂缝中坠落。黎的父亲（当时的家主）在这场灾难中为保护族人和领地战死。", "body": "### 海德纳事件（五年前）\n五年前，一场毁灭性的裂缝异象灾难降临海德纳领地。异象爆发时，天空被染成**血红色**，大量构造体从裂缝中坠落。黎的父亲（当时的家主）在这场灾难中为保护族人和领地**战死**。\r\n\r\n这场异象的能量之强烈，被伊瑟尔本人观测到**超出了机器测量的上限**。更关键的是，现场伴随强烈的元素波动，却**没有任何爆炸表征**——这意味着灾难的性质并非物理爆炸，而是更深层次的空间/能量层面的异变。\r\n\r\n海德纳事件对海德纳一族造成了深远的影响：黎的父亲战死，家族格局重塑。罪西本人也在这一事件中被改变了体质——海德纳事件的能量影响了他的身体，使他虽然无法适配元素，却获得了异常的**相容性**。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。\n旧事件追踪第六章揭露，后续设计要求三十章以后；救援经过也存在不同版本，勿混成单一确定历史。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "海德纳事件（五年前）", "role": "摘录来源"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-3350f7931de0", "title": "伯斯塔二号井矿难", "type": "事件", "aliases": [], "tags": [], "summary": "八年前，伯斯塔矿区二号井发生重大矿难事故。共有15名矿工被困井下，救援行动持续了35天，最终被困人员全员死亡。事故发生后，矿场方面仅支付了微薄的赔偿金给遇难者家属，此事在当地长期引发争议。", "body": "### 伯斯塔二号井矿难（八年前）\n八年前，伯斯塔矿区二号井发生重大矿难事故。共有**15名矿工被困**井下，救援行动持续了**35天**，最终被困人员**全员死亡**。事故发生后，矿场方面仅支付了**微薄的赔偿金**给遇难者家属，此事在当地长期引发争议。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "6eb229c307b17785", "heading": "伯斯塔二号井矿难（八年前）", "role": "摘录来源"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-02cafd367478", "title": "塔斯尤尔中央图书馆", "type": "地点", "aliases": [], "tags": [], "summary": "来自古文明的一个图书馆，坐落于一个大型古文明遗迹之中。其中的AI管理员莱拉不是一个简单的AI，与白羽辰和伊迪娅的关系相当要好。", "body": "### 塔斯尤尔中央图书馆\n来自古文明的一个图书馆，坐落于一个大型古文明遗迹之中。其中的AI管理员莱拉不是一个简单的AI，与白羽辰和伊迪娅的关系相当要好。\n\n### 塔斯尤尔中央图书馆\n来自古文明的图书馆，坐落于大型古文明遗迹之中。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "塔斯尤尔中央图书馆", "role": "摘录来源"}, {"documentId": "aa6050924e73cd55", "heading": "塔斯尤尔中央图书馆", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-c605e71359f4", "title": "塔斯尤尔城", "type": "地点", "aliases": [], "tags": [], "summary": "来自前文明那场浩劫的余响之一，其中留下了关于前文明许多对裂缝的观察记录，以及对前文明的记录，对于人类意义巨大。", "body": "### 塔斯尤尔城\n来自前文明那场浩劫的余响之一，其中留下了关于前文明许多对裂缝的观察记录，以及对前文明的记录，对于人类意义巨大。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "塔斯尤尔城", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-718d70cc8054", "title": "泰拉遗迹城", "type": "地点", "aliases": [], "tags": [], "summary": "前文明所建的最大的堡垒城市，坐标未知。本体隐藏在星球上一片永不散去的迷雾之中，想要进入只有从几座入口城市向着泰拉的方向不断前进，直到走进迷雾中，继续前进便能来到泰拉的入口。泰拉的科技和伊迪亚的索伦帝国似乎有些相似。白羽绫、伊迪亚、伊莉雅斯三人的据点设立于此。", "body": "### 泰拉遗迹城\n前文明所建的最大的堡垒城市，坐标未知。本体隐藏在星球上一片永不散去的迷雾之中，想要进入只有从几座入口城市向着泰拉的方向不断前进，直到走进迷雾中，继续前进便能来到泰拉的入口。泰拉的科技和伊迪亚的索伦帝国似乎有些相似。白羽绫、伊迪亚、伊莉雅斯三人的据点设立于此。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "泰拉遗迹城", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-50acafa590e4", "title": "诺斯卡尔高等学院", "type": "组织", "aliases": [], "tags": [], "summary": "学院的院长是一个非常强大的人，统合全部教育资源创建成学院，开放给所有国家所有学生上学。影子一族们对学院很是支持并有多方面的合作。院长制定了这里的规则，这里是所有国家和影子的中立地带。无论谁在学院就读期间，安全由学院保证，任何进入学院前的过往在这里不许追究。几乎世界上已知的地区国家", "body": "### 诺斯卡尔高等学院\n学院的院长是一个非常强大的人，统合全部教育资源创建成学院，开放给所有国家所有学生上学。影子一族们对学院很是支持并有多方面的合作。院长制定了这里的规则，这里是所有国家和影子的中立地带。无论谁在学院就读期间，安全由学院保证，任何进入学院前的过往在这里不许追究。几乎世界上已知的地区国家和当地政府都会把学生送入学院。\r\n\r\n### 学院分区\r\n\r\n学院内部分为中心区、教学区、实验区、活动区、生活区、使馆区。所有大区都被一个超大的立场护盾所保护，护盾内部会投影出天空和云层，以让学生们感受没有雨的世界。\r\n\r\n中心区为学院核心，院长、最高教务处、最高行政处都在中心区。中心区分为内外两层，外层对所有人开放，内层需要获得院长许可才能进入——白羽一族的一个基地正是中心区内层区域。\r\n\r\n教学区为学院正常授课区域，是各个教学楼的所在处。实验区是学院为理科课程搭建的大型实验场，各种实验仪器应有尽有。活动区为体育、战斗类科目上课的区域，学院大型活动一般在活动区的中央体育场举行，学院用了特殊科技使得中央体育场可以容纳近乎十万人。生活区是学生日常生活的地方，超市餐厅娱乐场地样样齐全。使馆区是学院对外来势力开放驻扎的区域。\r\n\r\n### 学院学制\r\n\r\n学院实行十年年毕业制。年级内部分为固定班、精英班、流动班。前三个年级为固定班，每一学年末进行评级测试，决定第二年的精英班人选。第四学年开始，精英班保持班级不变，其余各班变为流动式课表。第7学年开始，行政班级解散，学生结组找老师登记，以组为单位组成流动班，一组不超过4人。\r\n\r\n### 评级测试\r\n\r\n评级测试分为学科测试、战斗测试、体育测试和综合测试。对一般学生来说，学科测试占比60%，战斗和体育测试占比30%，综合测试占比10%。对专业方向需要战斗的学生来说，学科测试占比40%，战斗和体育测试占比50%，综合测试占比10%。测试成绩排名在年级前4000的可以进入本年级的精英班。\r\n\r\n### 战斗竞赛\r\n\r\n每一学年中后期，学院会举行全院的战斗竞赛活动，活动以战斗为核心，目的是让学生释放压抑的天性以及锻炼实力。活动分为团队积分赛和淘汰赛，团队积分赛赛项有护卫、占领、防守、遭遇战。\n\n### 诺斯卡尔高等学院——补充设定\n### 传送大厅\r\n\r\n学院在全世界各地设有入口节点，通过统一的**传送大厅**实现空间连通。学生与访客可通过任意一处入口节点直接进入学院的传送大厅，再中转到校内各区域。这一传送网络是学院维持\"中立地带\"属性的关键基础设施。\r\n\r\n### 中央体育场——空间嵌套技术\r\n\r\n中央体育场采用了远超常规建筑技术的**空间嵌套技术**：\r\n\r\n- 体育场本身被**嵌套在一个真实空间中的入口节点**内——从外部看只是一个不起眼的建筑，但一旦通过入口，内部便是可以容纳近乎十万人的巨型竞技场。\r\n- 观众席采用**悬浮座椅**设计，座椅通过反重力力场悬停在空中，围绕竞技场分布。\r\n- 进入体育场需要**连结申请**——观众通过个人终端提交入场申请，获批准后通过**转位按钮**被瞬间传送到对应的悬浮座位。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "诺斯卡尔高等学院", "role": "摘录来源"}, {"documentId": "2c6549cd854e0794", "heading": "诺斯卡尔高等学院——补充设定", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-63aba62b9801", "title": "星空之树", "type": "地点", "aliases": [], "tags": [], "summary": "塔罗斯上的第一个树，是空之树在此的投影，意味着这个地方的空间濒临崩溃，需要空之树的强制修正才能维持形态。这棵树位于星球的另一侧，目前只有极少旅人走到了这个树所在的位置并向外界传达了这个树的存在。", "body": "### 星空之树\n塔罗斯上的第一个树，是空之树在此的投影，意味着这个地方的空间濒临崩溃，需要空之树的强制修正才能维持形态。这棵树位于星球的另一侧，目前只有极少旅人走到了这个树所在的位置并向外界传达了这个树的存在。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "星空之树", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-09a7f6ee30e0", "title": "水晶之树", "type": "地点", "aliases": [], "tags": [], "summary": "塔罗斯上的第二个树，是时之树在此的投影。这意味着这个地方的时间极乱，错综复杂到了需要时之树把自己的枝杈投影过来才能稳定的状态。水晶之树隐藏在一个封闭的时空相位里，但已经有多个旅人被搅进这个相位的事件发生。它是一棵巨大的足有两公里直径的巨树，整体晶莹剔透，反射着虚假的日光。多数旅人", "body": "### 水晶之树\n塔罗斯上的第二个树，是时之树在此的投影。这意味着这个地方的时间极乱，错综复杂到了需要时之树把自己的枝杈投影过来才能稳定的状态。水晶之树隐藏在一个封闭的时空相位里，但已经有多个旅人被搅进这个相位的事件发生。它是一棵巨大的足有两公里直径的巨树，整体晶莹剔透，反射着虚假的日光。多数旅人在赶到树下触摸树之前就被扔出了这个相位。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "水晶之树", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-4b07cd68f858", "title": "裂空之树", "type": "地点", "aliases": [], "tags": [], "summary": "塔罗斯上的第三个树，是一种极为特殊的现象产物。裂缝将这个地方的空间撕开，延展出了一部分非实非复的数学真空位面，这种真空引来了法则的强制修正，但法则的修正没有完全生效，因此诞生出一个不属于实位面也不属于复位面却仍包含于复数集的第三类故障位面。裂空之树是吸满了时空力量的一个畸形之树，", "body": "### 裂空之树\n塔罗斯上的第三个树，是一种极为特殊的现象产物。裂缝将这个地方的空间撕开，延展出了一部分非实非复的数学真空位面，这种真空引来了法则的强制修正，但法则的修正没有完全生效，因此诞生出一个不属于实位面也不属于复位面却仍包含于复数集的第三类故障位面。裂空之树是吸满了时空力量的一个畸形之树，外形是一层无法描述的错乱物体生硬组合在一起——一个树形的、昏暗的、冰冷的、具有复数细小空间裂缝夹杂在其上的模因。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "裂空之树", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-83ab4a6da723", "title": "裂缝倒影", "type": "地点", "aliases": [], "tags": [], "summary": "裂空之树存在于裂缝倒影之中，这是一个不受法则约束、不受数字侵染的空间。", "body": "### 裂缝倒影\n裂空之树存在于裂缝倒影之中，这是一个不受法则约束、不受数字侵染的空间。\r\n\r\n---", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "裂缝倒影", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-5a4ee0911de1", "title": "伯斯塔城", "type": "地点", "aliases": [], "tags": [], "summary": "伯斯塔城是洛星一族的管辖地，也是贝伦-海德纳大陆上的重要城市。城市由多个风格的区域组成：", "body": "### 伯斯塔城\n伯斯塔城是洛星一族的管辖地，也是贝伦-海德纳大陆上的重要城市。城市由多个风格的区域组成：", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "伯斯塔城", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-23ff707df942", "title": "商业区", "type": "地点", "aliases": [], "tags": [], "summary": "现代化的城市核心区域，街道两旁矗立着玻璃幕墙建筑，商铺林立，人流密集。这里也是电子支付等现代化设施普及程度最高的区域。", "body": "### 商业区\n现代化的城市核心区域，街道两旁矗立着玻璃幕墙建筑，商铺林立，人流密集。这里也是电子支付等现代化设施普及程度最高的区域。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "商业区", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-20715c41b734", "title": "老城区", "type": "地点", "aliases": [], "tags": [], "summary": "保留了大量传统建筑风格的历史区域。石板铺就的街道蜿蜒曲折，铁铸路灯散发着温暖的橙黄色光芒，沿街的砖石建筑墙面上绘制着盖亚之主的大型壁画。天黑之后，路边树梢上可看到月花绽放的荧光。", "body": "### 老城区\n保留了大量传统建筑风格的历史区域。石板铺就的街道蜿蜒曲折，铁铸路灯散发着温暖的橙黄色光芒，沿街的砖石建筑墙面上绘制着**盖亚之主**的大型壁画。天黑之后，路边树梢上可看到**月花**绽放的荧光。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "老城区", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-df3a3a60083e", "title": "圣伯斯塔大教堂", "type": "地点", "aliases": [], "tags": [], "summary": "伯斯塔城内的教会核心建筑，规模宏大，是当地信徒的精神中心。", "body": "### 圣伯斯塔大教堂\n伯斯塔城内的教会核心建筑，规模宏大，是当地信徒的精神中心。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "圣伯斯塔大教堂", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-07968d399fa2", "title": "伯斯塔监测站", "type": "地点", "aliases": [], "tags": [], "summary": "位于伯斯塔城外的一处专门设施，用于实时监测周边区域的异象能量曲线变化。监测站装备精密的能量探测仪器，能在异象发生前及时发现能量波动异常，为城市预警争取时间。", "body": "### 伯斯塔监测站\n位于伯斯塔城外的一处专门设施，用于实时监测周边区域的异象能量曲线变化。监测站装备精密的能量探测仪器，能在异象发生前及时发现能量波动异常，为城市预警争取时间。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "伯斯塔监测站", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6ca3dd7eccb2", "title": "圣城贝伦蒂亚", "type": "地点", "aliases": [], "tags": [], "summary": "圣城贝伦蒂亚距离伯斯塔大致有八千公里远，是整个贝伦-海德纳大陆的核心城市，也是政治核心所在。远远望去可以看到非常洁白的城市，从城门进去可以看到整个城市最大的建筑——圣贝伦大教堂，那是全世界目前最大的教堂。圣城拥有先进的悬浮交通系统，相当具有科技感。", "body": "### 圣城贝伦蒂亚\n圣城贝伦蒂亚距离伯斯塔大致有八千公里远，是整个贝伦-海德纳大陆的核心城市，也是政治核心所在。远远望去可以看到非常洁白的城市，从城门进去可以看到整个城市最大的建筑——圣贝伦大教堂，那是全世界目前最大的教堂。圣城拥有先进的悬浮交通系统，相当具有科技感。\r\n\r\n圣城贝伦蒂亚同时也是**教宗驻地**，是创世教会的最高权力中心。教廷的所有重大决策、密件签发、教阶任命均在此进行。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "圣城贝伦蒂亚", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-3881ddf47dcc", "title": "海德纳领地", "type": "地点", "aliases": [], "tags": [], "summary": "海德纳一族的世袭领地，位于伯斯塔城外。庄园采用轴对称的古典建筑风格，与洛星一族的建筑风格截然不同。领地内拥有私人家用级别的天气模拟力场穹顶，可以将外部无尽的雨水隔绝在外，并在内部营造出适宜生活的晴好环境。庄园建筑庄重典雅，处处透露出古老家族的气度与品味。", "body": "### 海德纳领地\n海德纳一族的世袭领地，位于伯斯塔城外。庄园采用**轴对称的古典建筑风格**，与洛星一族的建筑风格截然不同。领地内拥有**私人家用级别的天气模拟力场穹顶**，可以将外部无尽的雨水隔绝在外，并在内部营造出适宜生活的晴好环境。庄园建筑庄重典雅，处处透露出古老家族的气度与品味。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "海德纳领地", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b3b49386678c", "title": "洛星—海德纳联合矿区", "type": "地点", "aliases": [], "tags": [], "summary": "位于伯斯塔城外约半小时车程，由洛星一族与海德纳一族共同管理。矿区入口是一座铁架拱门，内部有多处仓储设施（如一号仓库——灰白色钢结构大棚），并分布着数个矿井入口。", "body": "### 洛星—海德纳联合矿区\n位于伯斯塔城外约半小时车程，由洛星一族与海德纳一族共同管理。矿区入口是一座铁架拱门，内部有多处仓储设施（如一号仓库——灰白色钢结构大棚），并分布着数个矿井入口。\r\n\r\n### 矿场内部结构\r\n\r\n矿区包含多个不同状态的矿井：\r\n\r\n- **一号井**：已枯竭，处于半废弃状态，设备残旧。\r\n- **三号井**：老矿井，三十年前开凿，其中包含B段矿道等复杂的地下结构。\r\n- **竖直井道**：人工开凿的垂直竖井，用于连接不同深度的矿层。\r\n- **老采空区**：部分井与井之间存在因早年开采形成的采空区，结构不稳定，存在塌方隐患。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "洛星—海德纳联合矿区", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-554c7bcece5c", "title": "传送大厅", "type": "地点", "aliases": [], "tags": [], "summary": "学院在全世界各地设有入口节点，通过统一的传送大厅实现空间连通。学生与访客可通过任意一处入口节点直接进入学院的传送大厅，再中转到校内各区域。这一传送网络是学院维持\"中立地带\"属性的关键基础设施。", "body": "### 传送大厅\n学院在全世界各地设有入口节点，通过统一的**传送大厅**实现空间连通。学生与访客可通过任意一处入口节点直接进入学院的传送大厅，再中转到校内各区域。这一传送网络是学院维持\"中立地带\"属性的关键基础设施。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "传送大厅", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-bc171dc62a58", "title": "中央体育场", "type": "地点", "aliases": [], "tags": [], "summary": "中央体育场采用了远超常规建筑技术的空间嵌套技术：", "body": "### 中央体育场——空间嵌套技术\n中央体育场采用了远超常规建筑技术的**空间嵌套技术**：\r\n\r\n- 体育场本身被**嵌套在一个真实空间中的入口节点**内——从外部看只是一个不起眼的建筑，但一旦通过入口，内部便是可以容纳近乎十万人的巨型竞技场。\r\n- 观众席采用**悬浮座椅**设计，座椅通过反重力力场悬停在空中，围绕竞技场分布。\r\n- 进入体育场需要**连结申请**——观众通过个人终端提交入场申请，获批准后通过**转位按钮**被瞬间传送到对应的悬浮座位。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "2c6549cd854e0794", "heading": "中央体育场——空间嵌套技术", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-aa41864a5013", "title": "白羽一族", "type": "组织", "aliases": [], "tags": [], "summary": "白羽一族并非影子一族，但却对影子一族有着绝对的控制力，对待影子一族并不友善，许多影子对于白羽一族都是敬而远之。", "body": "### 白羽一族\n白羽一族并非影子一族，但却对影子一族有着绝对的控制力，对待影子一族并不友善，许多影子对于白羽一族都是敬而远之。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽一族", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b53e5e379dbc", "title": "七色议会", "type": "组织", "aliases": [], "tags": [], "summary": "来自千万年前的一段时期的回响，虽然七色已经不再是那七位，但对世界的影响力只增不减。", "body": "### 七色议会\n来自千万年前的一段时期的回响，虽然七色已经不再是那七位，但对世界的影响力只增不减。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "七色议会", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-804299cf3607", "title": "白羽绫", "type": "人物", "aliases": [], "tags": [], "summary": "白羽一族的实际掌控者之一，只做自己感兴趣的事情。对于自己的两个妹妹极其溺爱，但自身充满矛盾——时而神秘，时而残忍，时而宠溺，时而温柔。", "body": "### 白羽绫\n白羽一族的实际掌控者之一，只做自己感兴趣的事情。对于自己的两个妹妹极其溺爱，但自身充满矛盾——时而神秘，时而残忍，时而宠溺，时而温柔。\r\n\r\n对于任何影子一族，绫的名字都是禁忌中的禁忌，仅观察者与魔导会的最高领导者们知道存在一个未知。\r\n\r\n> \"这倒是新奇的一幕，值得我驻足观赏\"\r\n\r\n#### 白羽绫的本体与创生之树\r\n\r\n白羽绫是整本书最核心的人物之一，是世界的至高神明（整个宇宙）。她的本体超脱于可知域与未知域存在，直接挂在世界的墙外的。在可知域中，白羽绫透过复位面投射才能在可知域中自由行动。\r\n\r\n在可知域距离白羽绫本体最近的复位面附近，有一个独立存在的**创生之树**（可以理解为白羽绫本体），位于一个具有限制的空间中，一般无法被找到。雪就是在这片空间中意外诞生的。白羽绫注意到了她，给了她自我意识。\r\n\r\n白羽绫意在培养雪。雪从降生到现在已有八年，和三位旅人（白羽绫、伊莉雅斯、伊迪亚）的故事是在最后的三年发生的。\r\n\r\n#### 雪（伊维娅·希洛瓦）的关键点\r\n\r\n1. 雪是一个完全的创世神，只是暂时没有成长到那么强大。\r\n2. 雪是不被本宇宙干涉的——信息无法侵染到她，同样也无法证明她存在。\r\n3. 第三点目前不能透露。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽绫", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-aa41864a5013"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-a7d0814a9045", "title": "白羽辰", "type": "人物", "aliases": [], "tags": [], "summary": "白羽一族的实际掌控者之一，对外人冷漠但是对自己熟悉的人非常开放。对于自己的姐姐有着很深的感情，但是因为傲娇从不明说。对于自己的妹妹有着很强的保护欲，出现任何可能伤害到姐姐或妹妹的事情都会第一时间冲在前面。", "body": "### 白羽辰\n白羽一族的实际掌控者之一，对外人冷漠但是对自己熟悉的人非常开放。对于自己的姐姐有着很深的感情，但是因为傲娇从不明说。对于自己的妹妹有着很强的保护欲，出现任何可能伤害到姐姐或妹妹的事情都会第一时间冲在前面。\r\n\r\n对于任何影子一族，辰的名字都是禁忌中的禁忌，仅观察者与魔导会的最高领导者们知道存在一个未知。辰的存在，是白羽一族能够屹立于这颗星球的根本原因之一。\r\n\r\n> \"唯有在仁慈这一点上，你我别无二致\"\r\n\r\n**核心独白1：**\r\n- \"这就算结束了吗\"\r\n- \"我希望结束了\"\r\n- \"但显然不是\"\r\n- \"钟声已至，显然，刚刚开始。\"\r\n\r\n**核心对话1：**\r\n- \"世界在震荡。\"\r\n- \"是啊，在震荡，我们正在破坏创世规则，规则在试图修正。\"\r\n- \"你们的存在或许是我们仍然存在的原因。\"\r\n- \"并不，规则没有清除你们不是我们的功劳，是你们人类自己的努力。\"\r\n- \"我们在试图推翻时间的定点啊。\"\n\n### 白羽辰——补充设定\n### 辰与海德纳一族的旧交\r\n\r\n十年前，海德纳·黎的父亲曾将一只**表**托付给白羽辰保管，约定在合适的时机由辰**亲手交给黎**。这份委托是辰与海德纳一族之间深厚的旧交的见证。辰至今仍遵循着这份约定。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽辰", "role": "摘录来源"}, {"documentId": "fd311726f186a3f0", "heading": "白羽辰——补充设定", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-aa41864a5013"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-3f08c208525e", "title": "白羽芙萝拉", "type": "人物", "aliases": [], "tags": [], "summary": "白羽一族的实际掌控者之一，白羽三姐妹中最小的妹妹，常常代表七色议会的意志行动。对于自己的两位姐姐相当羡慕，也不乏对姐姐们的喜欢，但本人却是一个实打实的小鬼。", "body": "### 白羽芙萝拉\n白羽一族的实际掌控者之一，白羽三姐妹中最小的妹妹，常常代表七色议会的意志行动。对于自己的两位姐姐相当羡慕，也不乏对姐姐们的喜欢，但本人却是一个实打实的小鬼。\r\n\r\n对于任何影子一族，芙萝拉的名字意味着大麻烦的来临，因为七色议会绝不会无缘无故找上某一族。芙萝拉的存在，是白羽一族能够超越全部文明的根本原因之一。\r\n\r\n> \"保持理智，不然你会被自己的过去所吞噬\"\r\n\r\n**核心对话1：**\r\n- \"神裔们注意到了这边，那帮蛀虫也想在这个时候来分一杯羹。\"\r\n- \"恶心，比众神会议还恶心的吸血鬼，都这种时候了居然还在觊觎时间乱流中的能量。\"\r\n- \"辛苦你跑一趟了，借助裂缝的效应边界构筑防火墙应该不难。\"\r\n- \"嗯\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽芙萝拉", "role": "摘录来源"}], "related": ["entry-aa41864a5013"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-5fd7488da547", "title": "白羽议会", "type": "组织", "aliases": [], "tags": [], "summary": "白羽议会的议长，家族常务常由她与家主白羽梓共同处理。", "body": "### 白羽议会\n### 白羽雫\r\n\r\n白羽议会的议长，家族常务常由她与家主白羽梓共同处理。\r\n\r\n> \"在此，吾等定义，生命的价值\"\r\n\r\n**核心对话1：**\r\n- \"这件事情你们也预料到了吗？\"\r\n- \"这是固定的时刻，无法推翻。\"\r\n- \"我们要采取行动了，不能再观望了\"\r\n\r\n### 白羽梓\r\n\r\n白羽一族现任家主，白羽一族名义上的掌控者，但如果七色议会有介入或决议下达，需要优先执行。\r\n\r\n> \"诸君，竭力而为吧。\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽议会", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-f2243aa8918d", "title": "白羽雫", "type": "人物", "aliases": [], "tags": [], "summary": "白羽议会的议长，家族常务常由她与家主白羽梓共同处理。", "body": "### 白羽雫\n白羽议会的议长，家族常务常由她与家主白羽梓共同处理。\r\n\r\n> \"在此，吾等定义，生命的价值\"\r\n\r\n**核心对话1：**\r\n- \"这件事情你们也预料到了吗？\"\r\n- \"这是固定的时刻，无法推翻。\"\r\n- \"我们要采取行动了，不能再观望了\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽雫", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-7c44b1a3d961", "title": "白羽梓", "type": "人物", "aliases": [], "tags": [], "summary": "白羽一族现任家主，白羽一族名义上的掌控者，但如果七色议会有介入或决议下达，需要优先执行。", "body": "### 白羽梓\n白羽一族现任家主，白羽一族名义上的掌控者，但如果七色议会有介入或决议下达，需要优先执行。\r\n\r\n> \"诸君，竭力而为吧。\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽梓", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-77ab32448b35", "title": "白羽夏菲", "type": "人物", "aliases": [], "tags": [], "summary": "白羽一族中一个很酷的女孩子，和家主白羽梓关系极好。夏菲平时在学院的核心区内活动，也会偶尔去观看学院的竞赛。本次竞赛有白羽一族的孩子参加，夏菲承担了考核与管理队伍的职责，她本人无意参加比赛。", "body": "### 白羽夏菲\n白羽一族中一个很酷的女孩子，和家主白羽梓关系极好。夏菲平时在学院的核心区内活动，也会偶尔去观看学院的竞赛。本次竞赛有白羽一族的孩子参加，夏菲承担了考核与管理队伍的职责，她本人无意参加比赛。\r\n\r\n协助了院长的实验并在最后成神时救了雪一命，院长在学院内为她安排了一个不存在的院系的学生身份，以随时调动转学转入任务学院。\r\n\r\n个人爱好是二次元，可爱的耳机从不离身，爱跳宅舞穿着很二次元，智商超高武力不低，为了装帅偶尔还会带单片眼镜。最后亲手杀掉了星雨，即使二人关系本来不错。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽夏菲", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-fb9b5d925b3f", "title": "白羽希纳", "type": "人物", "aliases": ["希娜"], "tags": [], "summary": "白羽一族旁系的大小姐，本家负责办一些主家不方便直接动手的黑事。和夏菲一起长大，对夏菲言听计从，乖巧至极，对待其他人如同玩物，充分体现了黑道千金这个词的意思。", "body": "### 白羽希纳\n白羽一族旁系的大小姐，本家负责办一些主家不方便直接动手的黑事。和夏菲一起长大，对夏菲言听计从，乖巧至极，对待其他人如同玩物，充分体现了黑道千金这个词的意思。\r\n\r\n在学院篇中协助夏菲收拾一些不安分的学生，在罪西失控后在底层硬生生拉住罪西四个小时后力竭昏迷。非常喜欢玩弄星雨，和星雨关系不错。\r\n\r\n> \"死吧。\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "白羽希纳", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6504bcf09661", "title": "辰の咖啡馆", "type": "地点", "aliases": [], "tags": [], "summary": "辰在诺斯卡尔高等学院生活区经营的咖啡馆是一个极小的门面，店内只有一位咖啡师（辰本人）。咖啡的品质极高，但口味极苦——然而苦味之后会涌上一股独特的果香，让喝过的人难以忘怀。", "body": "### 辰の咖啡馆\n辰在诺斯卡尔高等学院生活区经营的咖啡馆是一个**极小的门面**，店内**只有一位咖啡师**（辰本人）。咖啡的品质极高，但口味**极苦**——然而苦味之后会涌上一股**独特的果香**，让喝过的人难以忘怀。\r\n\r\n伊瑟尔是这家咖啡馆的**常客**，经常以私下样貌到访。辰也曾**主动向洛星雪发出邀请**，让她有空来咖啡馆坐坐。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "fd311726f186a3f0", "heading": "辰の咖啡馆", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-2d5a4791f141", "title": "创世教会", "type": "组织", "aliases": [], "tags": [], "summary": "创世教会并非影子，而是一个几乎统治全世界的庞大神权教廷，以神的名义统治世间，但真正实现了爱民如子。", "body": "### 创世教会\n创世教会并非影子，而是一个几乎统治全世界的庞大神权教廷，以神的名义统治世间，但真正实现了爱民如子。\r\n\r\n他们信仰着盖亚之主，使用着来自盖亚的法力。他们与那些信奉着虚空之主的异教徒势不两立，保护着人民不受异教徒的伤害。\r\n\r\n## 教会的真相\r\n\r\n> **读法提醒**：主大纲中「盖亚之主只是一个谎言」一句，**「谎言」指的是双簧剧本这一层，而不是「神明不存在」**。神明真实存在。\r\n\r\n**表层（民众所见）**：民众信仰**盖亚之主**，认为教会使用的法力来自盖亚。**虚空之主**是搞破坏的邪神，其信徒即\"异教徒\"。**教会带头反抗虚空之主**，保护人民不受异教徒伤害——这是教会统治合法性的来源。\r\n\r\n**真相（教会高层知情）**：教会的最高领导层——教宗和六个至高主教，以及部分高层——都知道所谓神明的真正面目。**盖亚之主与虚空之主是同一个存在**，即**白羽三姐妹**；所谓\"异教徒\"是**白羽一族所假扮**的。历代教宗与至高主教都面见过真正的神明，那个被民众称为虚空之主的存在。\r\n\r\n### 双簧的本质\r\n\r\n- **盖亚之主**是**偶尔降恩**的一方，是教会推给民众的信仰对象。\r\n- **虚空之主**是**搞破坏**的邪神，是被反抗的对象。\r\n- **教会带头反抗虚空之主**：树立一个可见的、持续存在的恶，民众才有理由依赖教会与盖亚的庇护。\r\n- 让人民去信一个偶尔施恩的神本就不易；而当\"教会一直在保护你\"成为日常，信仰便顺理成章。这就是这套双簧的目的——控制民众、巩固教会。\r\n- 神明与教会达成合作，**表面上水火不容**。\r\n\r\n## 核心成员\n\n### 教会的真相\n> **读法提醒**：主大纲中「盖亚之主只是一个谎言」一句，**「谎言」指的是双簧剧本这一层，而不是「神明不存在」**。神明真实存在。\r\n\r\n**表层（民众所见）**：民众信仰**盖亚之主**，认为教会使用的法力来自盖亚。**虚空之主**是搞破坏的邪神，其信徒即\"异教徒\"。**教会带头反抗虚空之主**，保护人民不受异教徒伤害——这是教会统治合法性的来源。\r\n\r\n**真相（教会高层知情）**：教会的最高领导层——教宗和六个至高主教，以及部分高层——都知道所谓神明的真正面目。**盖亚之主与虚空之主是同一个存在**，即**白羽三姐妹**；所谓\"异教徒\"是**白羽一族所假扮**的。历代教宗与至高主教都面见过真正的神明，那个被民众称为虚空之主的存在。\r\n\r\n### 双簧的本质\r\n\r\n- **盖亚之主**是**偶尔降恩**的一方，是教会推给民众的信仰对象。\r\n- **虚空之主**是**搞破坏**的邪神，是被反抗的对象。\r\n- **教会带头反抗虚空之主**：树立一个可见的、持续存在的恶，民众才有理由依赖教会与盖亚的庇护。\r\n- 让人民去信一个偶尔施恩的神本就不易；而当\"教会一直在保护你\"成为日常，信仰便顺理成章。这就是这套双簧的目的——控制民众、巩固教会。\r\n- 神明与教会达成合作，**表面上水火不容**。\n\n### 补充设定\n### 教阶体系\r\n\r\n创世教会实行严格的四级教阶制度（自上而下）：\r\n\r\n1. **教宗** —— 教会最高领袖\r\n2. **至高主教** —— 直接辅佐教宗，共六位\r\n3. **大主教** —— 各教区负责人\r\n4. **主教** —— 基层教区管理者\r\n\r\n### 教宗密件传递机制\r\n\r\n教宗签发最高级别密令的流程极为严谨：\r\n\r\n- 密件以**纸质形式**书写和封印，不经过任何电子或魔法传输。\r\n- 由**圣女**亲自负责最高级别密件的传递任务，确保中途不被截获或篡改。\r\n- 收件人阅读后必须**立即焚烧**密件（阅后即焚），不留存任何物理证据。\r\n\r\n教宗**绯吉亚·伊莎梅莱**曾亲自签发过涉及洛星一族相关的密件。\r\n\r\n> **与神谕的区别**：密件＋圣女亲送是**教宗自己的对外秘密通讯手段**；而**神谕**是绫（教会所拜的那位神明）**通过白羽一族中的专人**直接传达的信息。两条线互不相通。\r\n\r\n### 盖亚之主\r\n\r\n**祂是世间真实存在的神明**——真正的神明是**白羽三姐妹**，盖亚之主与虚空之主本是同一存在、两个名号（见上文「教会的真相」）。**教会所拜、也是历代教宗与至高主教所面见的那一位，是绫本人**；另外两位对这个世界而言身份始终未知。这句事实在教会高层中是公开的秘密；在普通民众中，盖亚之主更多地被视为精神信仰的对象。\r\n\r\n在教会体系中，\"**盖亚之主知晓此事**\"是一句具有绝对权威的声明——它意味着某件事的真实性或正当性已经被神明本人确认，无人可以质疑。\r\n\r\n### 教会工坊\r\n\r\n教会拥有自建的**力场装置制造工坊**，专门负责生产各类天气模拟力场、防护力场和其他基于古代技术的装置。这些工坊的产品既服务于教会自身需求，也偶尔以高昂价格出售给外部势力。\r\n\r\n### 民间救援协调\r\n\r\n除了宗教职能外，教会在民间也承担着实实在在的**救援协调**角色。在异象灾害、矿难等重大事件发生时，教会会派出专门人员参与救援协调工作，协助疏散民众、提供物资援助，在世俗层面维持着爱民如子的形象。\r\n\r\n### 政治地位与责任\r\n\r\n创世教会是**名义上的世界政府**，统治影子一族。这里的\"名义\"有两个重点：\r\n\r\n- **武力**：教会拥有自己的武力组织——**圣殿骑士团**，至今存在。\r\n- **责任**：教会在实质上担起了**裂缝异象后的救灾工作**与各类**资源统筹**责任。这才是\"世界政府\"之名的真正落点——名分是名义的，担子是真的。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "7265b147ad084f8a", "heading": "创世教会", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-9ba0af82722e", "title": "绯吉亚·伊莎梅莱", "type": "人物", "aliases": [], "tags": [], "summary": "现任教宗，是一个不缺乏手段且分得清是非的人。称不上有正义感，但教会在他的领导下光明磊落，很少有阴谋诡计。", "body": "### 绯吉亚·伊莎梅莱（教宗）\n现任教宗，是一个不缺乏手段且分得清是非的人。称不上有正义感，但教会在他的领导下光明磊落，很少有阴谋诡计。\r\n\r\n但对于身边比较近的人，常常会很轻易的相信。正因如此，帝国特遣小队才能如此轻易的腐化掉教会的至高主教雷尔斯。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "7265b147ad084f8a", "heading": "绯吉亚·伊莎梅莱（教宗）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-9d8e58674464", "title": "希帕里亚·克鲁斯", "type": "人物", "aliases": [], "tags": [], "summary": "现任圣女，是一个完完全全不像圣女的人。武器不离身，裙子下的腿环上还会挂着小手枪。", "body": "### 希帕里亚·克鲁斯（圣女）\n现任圣女，是一个完完全全不像圣女的人。武器不离身，裙子下的腿环上还会挂着小手枪。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "7265b147ad084f8a", "heading": "希帕里亚·克鲁斯（圣女）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-803cbd7b99eb", "title": "柯维娜·玛拉", "type": "人物", "aliases": [], "tags": [], "summary": "（教会成员，详细信息待补充）", "body": "### 柯维娜·玛拉\n（教会成员，详细信息待补充）\r\n\r\n---", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "7265b147ad084f8a", "heading": "柯维娜·玛拉", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-e0d2d7acc125", "title": "盖亚之主", "type": "概念", "aliases": [], "tags": [], "summary": "祂是世间真实存在的神明——真正的神明是白羽三姐妹，盖亚之主与虚空之主本是同一存在、两个名号（见上文「教会的真相」）。教会所拜、也是历代教宗与至高主教所面见的那一位，是绫本人；另外两位对这个世界而言身份始终未知。这句事实在教会高层中是公开的秘密；在普通民众中，盖亚之主更多地被视为精", "body": "### 盖亚之主\n**祂是世间真实存在的神明**——真正的神明是**白羽三姐妹**，盖亚之主与虚空之主本是同一存在、两个名号（见上文「教会的真相」）。**教会所拜、也是历代教宗与至高主教所面见的那一位，是绫本人**；另外两位对这个世界而言身份始终未知。这句事实在教会高层中是公开的秘密；在普通民众中，盖亚之主更多地被视为精神信仰的对象。\r\n\r\n在教会体系中，\"**盖亚之主知晓此事**\"是一句具有绝对权威的声明——它意味着某件事的真实性或正当性已经被神明本人确认，无人可以质疑。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "7265b147ad084f8a", "heading": "盖亚之主", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-0a0cf0b79836", "title": "观察者一族", "type": "组织", "aliases": [], "tags": [], "summary": "观察者一族是一个极其特殊的影子，这个影子不是家族，而是支持任何对于观察与实验未知有兴趣的人加入。加入观察者意味着离开原有的一切生活。", "body": "### 观察者一族\n观察者一族是一个极其特殊的影子，这个影子不是家族，而是支持任何对于观察与实验未知有兴趣的人加入。加入观察者意味着离开原有的一切生活。\r\n\r\n很多影子一族与其保持着友好的交流，有时提供支持。其本身实力极其强大，超越几乎所有影子，除了同样特殊的魔导研究会。总部位于奈丹浮空城。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "acd80358342390ae", "heading": "观察者一族", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-98e80087a33e", "title": "卡斯伊尔", "type": "人物", "aliases": [], "tags": [], "summary": "观察者们的最高领导者，能力极强。通过自己的计算与干涉建立了一个时间上的定点，使得这一切发生。", "body": "### 卡斯伊尔\n观察者们的最高领导者，能力极强。通过自己的计算与干涉建立了一个时间上的定点，使得这一切发生。\r\n\r\n观察、实践、证明——这是他所坚信的万物法则。\r\n\r\n善于伪装，为达目的不择手段。在曾经的时候，他还是一个骚话不断的二货，为了自己的想法付出行动，不喜欢被规则束缚。曾经的战斗竞赛的第一名，与他们的小队一起。卡斯伊尔独自开创了观察者组织。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "acd80358342390ae", "heading": "卡斯伊尔", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-0a0cf0b79836"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-9fc82f0b545c", "title": "艾斯克", "type": "人物", "aliases": [], "tags": [], "summary": "人体基因研究院院长，虽然在卡斯伊尔的严格监控下，减少了违背人类道德的部分人体实验。在研究院中，有部分高权限的地方还有着一些见不得人、违背道德的实验。", "body": "### 艾斯克\n人体基因研究院院长，虽然在卡斯伊尔的严格监控下，减少了违背人类道德的部分人体实验。在研究院中，有部分高权限的地方还有着一些见不得人、违背道德的实验。\r\n\r\n> 人死就是死了，没有办法再活过来。这是共识，我是最明白的，也是最认可的。身为最顶尖的生物学家，每次做的实验都是在论证这个道理。正因为这样，每一次在那些生物上进行实验会尽可能的快速结束他们的生命。\r\n>\r\n> 我有一个秘密，在研究所里，有一个我喜欢的人，在实验结束后，她喜欢带我在满是森林中散步，然后找到一处阳光明媚的草地中躺下。阳光照在我们的脸上，惬意传满全身。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "acd80358342390ae", "heading": "艾斯克", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-72c1e1147033", "title": "雨桃", "type": "人物", "aliases": [], "tags": [], "summary": "在一次任务中死亡，成为艾斯克的实验素材，后被研究于复活，成为第一个复活体，但有缺陷。", "body": "### 雨桃\n在一次任务中死亡，成为艾斯克的实验素材，后被研究于复活，成为第一个复活体，但有缺陷。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "acd80358342390ae", "heading": "雨桃", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-bdf967fe348b", "title": "E-723", "type": "人物", "aliases": [], "tags": [], "summary": "艾斯克人体克隆的成功品。", "body": "### E-723\n艾斯克人体克隆的成功品。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "acd80358342390ae", "heading": "E-723", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-bd506335f695", "title": "魔法研习会", "type": "组织", "aliases": ["魔导会"], "tags": [], "summary": "致力于研究古代技术应用的组织，可以称得上与观察者平级。拥有很多古代文献资料，对古代技术的应用和知识的储备强于观察者，但技术的原理理解以及创造性改进不如观察者。", "body": "### 魔法研习会\n致力于研究古代技术应用的组织，可以称得上与观察者平级。拥有很多古代文献资料，对古代技术的应用和知识的储备强于观察者，但技术的原理理解以及创造性改进不如观察者。\r\n\r\n发现并改造了以应用为核心的一整套魔法体系——实际上是古代文明创造的某种未知元素，对人亲和，亲和力强的人能够控制使用这类元素。是伊诗渊在某个古代遗迹中开启的生产制造并第一个开始研究这类元素。\r\n\r\n> **术语说明**：这种未知元素在宇宙中的通用名称为\"元素\"，但元素理论不是这颗星球上能接触到的理论。元素这个概念只在魔导会内部有所研究，对外界是绝密理论。魔导会内部不称其为\"元素\"，而称其为**\"魔力\"**，并对外给出了魔力的一些使用方法。塔罗斯人并不知道元素的存在。所有\"术式\"\"魔法\"一类的东西都源于魔导会对魔力的研究。\r\n\r\n魔法研习会掌握着许多不为人知的秘典，其中包括一个关键的预言。总部位于星坠城。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "a90dc934a62f7501", "heading": "魔法研习会", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-d3c9062c484b", "title": "伊诗渊", "type": "人物", "aliases": [], "tags": [], "summary": "魔导会的领导者，对古代技术的了解程度甚至高于卡斯伊尔。与卡斯伊尔并不对付，两个人互相非常了解彼此却又非常敌视彼此，处于一种宿敌和挚友的中间态。", "body": "### 伊诗渊\n魔导会的领导者，对古代技术的了解程度甚至高于卡斯伊尔。与卡斯伊尔并不对付，两个人互相非常了解彼此却又非常敌视彼此，处于一种宿敌和挚友的中间态。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "a90dc934a62f7501", "heading": "伊诗渊", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-bd506335f695"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-24fabff782ef", "title": "星核计划", "type": "事件", "aliases": [], "tags": [], "summary": "创立魔导会后不久，伊诗渊开启了星核计划——一项以星坠城的圣物\"主星\"为核心的项目，目的是将主星武器化。在刚提出这个项目的时候遭到了来自伊瑟尔的否定。除去项目本身的危险性以外，伊瑟尔不希望看到双方走上军备竞赛的道路，她要把双方的武器项目限制在一个安全且平衡的状态上。", "body": "### 星核计划\n创立魔导会后不久，伊诗渊开启了星核计划——一项以星坠城的圣物\"主星\"为核心的项目，目的是将主星武器化。在刚提出这个项目的时候遭到了来自伊瑟尔的否定。除去项目本身的危险性以外，伊瑟尔不希望看到双方走上军备竞赛的道路，她要把双方的武器项目限制在一个安全且平衡的状态上。\r\n\r\n即使被否定，伊诗渊依旧没有放弃星核计划，这自然瞒不过院长。在雪他们察觉到了星核计划之后，伊瑟尔暗示他们去阻止这件事情，伊诗渊被迫放弃这一计划。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "a90dc934a62f7501", "heading": "星核计划", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-bd506335f695"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-475a95fc5204", "title": "日亚一族", "type": "组织", "aliases": [], "tags": [], "summary": "日亚一族是\"盘亘在南部大陆的巨大家族\"，势力遍布塔罗斯南大陆，财力雄厚、影响力深远。", "body": "### 日亚一族\n日亚一族是**\"盘亘在南部大陆的巨大家族\"**，势力遍布塔罗斯南大陆，财力雄厚、影响力深远。\r\n\r\n在与魔导会和其他影子一族的关系中，日亚一族被外界评价为**\"极力讨好魔导会的家犬\"**——他们通过向学院和各大势力提供巨额赞助来巩固自身地位，是**给诺斯卡尔高等学院赞助最多的家族**。\r\n\r\n日亚一族的真正目的与**洛星一族的圣遗物**有关——他们觊觎这件宝物已久，一直在寻找获取的机会。家族**现任继承人纳尔留斯**（同时也是2506班学生之一）在学院中承担着代表家族利益的任务。\r\n\r\n日亚一族与洛星一族之间存在着数代的竞争与对抗关系，这种关系在纳尔留斯入读学院后进入了一个新的阶段。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "a90dc934a62f7501", "heading": "日亚一族", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b38bde6d1541", "title": "罪孽剧团", "type": "组织", "aliases": [], "tags": [], "summary": "一个组织，更多人喜欢叫他罪孽剧团。讲述罪孽的故事，演绎救赎罪孽的事情，让人们理解何为恶，理解善的存在。", "body": "### 罪孽剧团\n一个组织，更多人喜欢叫他罪孽剧团。讲述罪孽的故事，演绎救赎罪孽的事情，让人们理解何为恶，理解善的存在。\r\n\r\n恶并非恶，人自来并非恶。善并非善，人不为善。人更多的是为了自己——名誉，生命，意志，又或者是其他的信仰。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "罪孽剧团", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-812276c286b1", "title": "齐霆", "type": "人物", "aliases": ["导演"], "tags": [], "summary": "创始人，成立初期就存在的人，剧院的顶层之一，但目前处于失踪状态。", "body": "### 导演（齐霆）\n创始人，成立初期就存在的人，剧院的顶层之一，但目前处于失踪状态。\r\n\r\n性格沉默、优雅，渴望对于自我的答案。自我矛盾的人——善良就一定不会残暴吗？这是他思考的道理，而这个人也是这个问题的实验。他更喜欢这个问题体现在\"演出\"中。\r\n\r\n他也是善良的，不愿看到死亡，又让他们无痛的离去……他也是恶魔，赐予痛苦的挣扎，又赐予绝望的离开。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "导演（齐霆）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-8f483cc50156", "title": "墨凌", "type": "人物", "aliases": ["骸"], "tags": [], "summary": "在前文明遗迹中被骸捡回来的孩子，本身是前文明的遗民，记忆被封存在泰拉遗迹城内，不断吸引着他前去取回。他从小就展露出了异于常人的能力——无论是超乎常人的力量和敏锐的洞察力，以及大量遗迹机械对他的回应，都证明了他的不凡。", "body": "### 骸（墨凌）\n> \"我们的生命不过是神明所写的几行剧本，既如此，何不与我一同共赴这盛大的终幕\"\r\n\r\n在前文明遗迹中被骸捡回来的孩子，本身是前文明的遗民，记忆被封存在泰拉遗迹城内，不断吸引着他前去取回。他从小就展露出了异于常人的能力——无论是超乎常人的力量和敏锐的洞察力，以及大量遗迹机械对他的回应，都证明了他的不凡。\r\n\r\n**人物性格：** 阴暗，怀诈暴憎，为了计划不择手段。\r\n\r\n- 面对星言：指挥，骚男，一个合格的大脑，喜欢嘴毒罪西，喜欢捉弄崔卿菱，调韧峰的狙击镜。\r\n- 面对罪孽剧团：与他们有疏远感。\r\n- 面对骸：父亲，但是为了计划的实施……\n\n### 墨凌\n一个隐藏的强者，来自超古代文明的回响。性格温柔，关心身边的朋友，实力远超他人。见罪孽剧团——骸（墨凌）。\n\n### 墨凌的班级调查\n墨凌在入学前对2506班**全班同学做过系统性的情报调查**。她对班上每一位同学的背景和实力都有远超常人的了解，这也是她能在班级中保持低调却游刃有余的原因。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。\n原文班级调查段使用“她”，第四章后补充明确星言成员为男生；保留原文等待修订。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "骸（墨凌）", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "墨凌", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "墨凌的班级调查", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b70f3a3556cb", "title": "厄", "type": "人物", "aliases": ["演员"], "tags": [], "summary": "剧院高层之一。性格沉默，喜欢安静，更多的是喜欢在自己的基地中科研，没有目的性的科研。自我否定，也是观察到了\"真相\"的人。", "body": "### 厄（演员）\n剧院高层之一。性格沉默，喜欢安静，更多的是喜欢在自己的基地中科研，没有目的性的科研。自我否定，也是观察到了\"真相\"的人。\r\n\r\n### 噤声的天才\r\n\r\n没有任何身份的人研究的成果被别人作为垫脚石。他能做什么呢？被霸占自己的成果，发声？报复？好吧，他什么都做不了。天才？小丑而已。他站在了天台上——这位仅用自己做出了无功耗的传输设施的人，他创造了一项改变时代的东西，只是现在，他准备将自己的生命终结。\r\n\r\n骸骨看到了这些，他出手了。那些盗窃名誉的人被发现在家自杀，用他们的血在墙上写下了\"我有罪\"。然而这样恶劣的事情被莫名地压了下去。噤也就这么出来了。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "厄（演员）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-955d26a2f379", "title": "婪", "type": "人物", "aliases": ["舞者"], "tags": [], "summary": "剧院高层之一。时常哭泣，但是极其温柔。", "body": "### 婪（舞者）\n剧院高层之一。时常哭泣，但是极其温柔。\r\n\r\n> \"她生来就是天平上的砝码，用来衡量他们的价值。为了可以让砝码的重量足以让天平倾斜，可以让他们获得胜利，砝码的任何都无需在意。因为砝码只是获得他们想要的工具。\"\r\n\r\n折断双翼的鸟儿在金丝鸟笼中仰望着天空，而笼外的鸟却在期待着自己关入这牢笼。她想逃离，走出这被规定好的人生——她成为了那只金丝雀，被关入那金碧辉煌的牢笼。\r\n\r\n只是命运会平等地将机会给予每个人，只是转瞬即逝。她抓住了打开命运枷锁的钥匙，冲出了那个牢笼。这也是双向的救赎——那个家伙在与他相识后，一步步引导婪摆脱了被那些人控制，随后他将那个牢笼打破，她就这样逃了出来。\r\n\r\n这就是她的故事，也就是她的墓志铭：**牢笼，门，希望**。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "婪（舞者）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-cf22bc1bd07e", "title": "怒", "type": "人物", "aliases": [], "tags": [], "summary": "（见阳羡）", "body": "### 怒\n（见阳羡）", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "怒", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-d4b772a499f2", "title": "屈", "type": "人物", "aliases": [], "tags": [], "summary": "很有自尊心的少年。", "body": "### 屈\n很有自尊心的少年。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "9b13423e873518cf", "heading": "屈", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-55a3c2704d61", "title": "伊瑟尔", "type": "人物", "aliases": [], "tags": [], "summary": "伊瑟尔的真实身份是白羽绫的复制体——原初的复制体。不同于组成了代行者的其他复制体，这个复制体最像白羽绫。", "body": "### 伊瑟尔（院长）\n> \"我将万物汇于一点，在此奉上，世界的终幕。\"\r\n\r\n伊瑟尔的真实身份是**白羽绫的复制体**——原初的复制体。不同于组成了代行者的其他复制体，这个复制体最像白羽绫。\r\n\r\n白羽绫给了她极大的自由度，不必拘泥于什么，就像白羽绫自己一样，随心所欲地去做自己喜欢的事情。长久的时光让她开始思考一个问题：自己存在的意义是什么。她曾向白羽绫问过这个问题，但被告知需要自己去寻找答案。\r\n\r\n最终，她选择融入普通生物的社会，尾随着白羽绫的足迹，观察着她的动向，体会着生命的意义。使用伊瑟尔这个姓氏，也是对于学院最终归属的表露——学院的最终归属权属于伊迪亚，那个喜欢读书的少女。她和伊迪亚之间有着数不清的往事，算得上是那位神明的挚友。\r\n\r\n**核心对话1：**\r\n- \"你还是推出来了那个公式，所以，你要改变这个混乱结局？\"\r\n- \"你终究还是做出来相反的决定，人类的罪人，却是世界的守护者。你倒是配得上我最优秀的弟子。\"\r\n\r\n**核心对话2：**\r\n- \"真的有必要做到这种地步吗，一个本土文明而已，你要为他们做到这种地步？\"\r\n- \"绫大人不也做了很多吗，甚至在本地催化了一个新的神的孵化不是吗。\"\r\n- \"她啊，对她来说这只是顺手的事情吧。\"\n\n### 伊瑟尔——补充设定\n### 双面孔/双身份\r\n\r\n伊瑟尔在日常生活中拥有**两个完全不同的面孔和身份**：\r\n\r\n- **工作用样貌**：白发、庄严、学院院长的威严形象，是大多数学生和教职工所见到的样子。\r\n- **私下用样貌**：一个矮小女孩的形象，用于自由行动和私密会面。这个身份让她能够不受院长身份的束缚，在学院内外自由活动。\r\n\r\n### 与洛星雪的前缘\r\n\r\n一年前，伊瑟尔曾与白羽绫一起**亲自训练洛星雪**。在那段时间里，伊瑟尔给她起了绰号**\"小蛋糕\"**。这是雪与伊瑟尔之间独有的亲昵过往，也是为什么雪见到伊瑟尔时会产生\"模糊的熟悉感\"的原因。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "伊瑟尔（院长）", "role": "摘录来源"}, {"documentId": "3e2ce61244f194ad", "heading": "伊瑟尔——补充设定", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-50acafa590e4"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-c651ae2a7cd1", "title": "利德尔", "type": "人物", "aliases": [], "tags": [], "summary": "前某国家退役教官，在学院任职战术指导老师。据传闻他和魔导会的战斗人员交战后全身而退。为人和蔼，在教学中容不得一点沙子，似乎有着一些故事。", "body": "### 利德尔\n前某国家退役教官，在学院任职战术指导老师。据传闻他和魔导会的战斗人员交战后全身而退。为人和蔼，在教学中容不得一点沙子，似乎有着一些故事。\n\n### 利德尔——补充设定\n### 教学风格\r\n\r\n利德尔的首课流程固定为：**三圈热身跑** -> **摸底测试** -> **每人一学分** -> 根据测试结果为每位学生制定**单独训练计划**。他的教学风格**严厉但公正**，对所有人都一视同仁，绝不容忍偷懒，但从不会因为个人好恶刁难学生。\r\n\r\n> 前某国家退役教官，在学院任职战术指导老师。据传闻他和魔导会的战斗人员交战后全身而退。为人和蔼，在教学中容不得一点沙子，似乎有着一些故事。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "利德尔", "role": "摘录来源"}, {"documentId": "3e2ce61244f194ad", "heading": "利德尔——补充设定", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-4d8166e88520", "title": "银", "type": "人物", "aliases": [], "tags": [], "summary": "兼具智慧、平等、宠爱、独立于一身的人，不畏惧任何困难。是2506班的班主任，科研能力极强，教学负责认真。负责教学的科目是初等数学。", "body": "### 银（2506班班主任）\n兼具智慧、平等、宠爱、独立于一身的人，不畏惧任何困难。是2506班的班主任，科研能力极强，教学负责认真。负责教学的科目是**初等数学**。\r\n\r\n银本身并非影子之一，但因为自身的强大和伊瑟尔的支持，她在影子中的行动极其自由且力量强大，但她几乎从不在影子中出现。她在某次遗迹开拓中发现了因意外失忆的白柔，将她带回学院成为自己的助手。\r\n\r\n银和洛星宁见过，但不是师生关系，只是请教过部分问题。银和雪从没见过，雪不知道银的任何信息。同样，雪在正式入学前从未见过学院的任何老师，也不知道学院任何老师的任何信息。\n\n### 银\n兼具智慧、平等、宠爱、独立于一身的人，不畏惧任何困难。很在乎几个自己培养起来的孩子，将她们视如己出，对孩子们甚至可以说是溺爱。银本身并非影子之一，但因为自身的强大和伊瑟尔的支持，她在影子中的行动极其自由且力量强大。但她几乎从不在影子中出现。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "银（2506班班主任）", "role": "摘录来源"}, {"documentId": "aa6050924e73cd55", "heading": "银", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-a874a024e8ca", "title": "库洛伊", "type": "人物", "aliases": [], "tags": [], "summary": "某位陨落的神明遗留的武器，早已拥有自我意识。", "body": "### 库洛伊\n某位陨落的神明遗留的武器，早已拥有自我意识。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "库洛伊", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-11563e62a5e5", "title": "许寂", "type": "人物", "aliases": [], "tags": [], "summary": "性格温柔，认真，同时不失威严，有着自己的固执。不吝啬分享自己的零食给学生，也会和学生聊些不属于学习的话题。", "body": "### 许寂\n性格温柔，认真，同时不失威严，有着自己的固执。不吝啬分享自己的零食给学生，也会和学生聊些不属于学习的话题。\r\n\r\n很早之前，他和那些人曾在一个时代——那是一个混乱的时代，谁都是黑马，谁都会跌下神坛。有个人站上山巅，认为脚下皆为蝼蚁，而他傲慢地向上看去想要知道最上面的风景。而天上什么都没有，被另一座山挡着——那是一座更雄伟的山，直通天际，穿越时空，它名为**无限**。\r\n\r\n无知的少年向着这座名为无限的山轻言宣誓，要将它征服于脚下。年少无知并不是值得被嘲笑的理由，他在登上山的那一刻就注定了他后面的旅途。\r\n\r\n狂妄只有连续的胜利才会一直下去，当他失败，狂妄散去，留下的皆为遗憾和教训。\r\n\r\n> 许寂（齐老师）对学院有所不满，但这不满是对上层、指向院长的。他对学生是非常和蔼友善且负责的好老师。原因暂且不能说。\r\n\r\n### 许寂脑内的另一个声音\r\n\r\n许寂的脑海中存在着**另一个声音**——一个空灵的女性声音。这个声音与他有着深层的联系，在关键的时刻会给予他提示或警告。声音的来源和性质尚不明确，但似乎与许寂的真实身份和他来到学院的深层原因有关。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "许寂", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6ee2f49f0225", "title": "张婷", "type": "人物", "aliases": [], "tags": [], "summary": "遗迹工程导论课程的授课教师，是一位年轻女性。她的教学风格极度严苛，对学生的课程表现要求极高，几乎没有通融余地。尽管学生们对她又敬又畏，但她的教学效果在学院中首屈一指。", "body": "### 张婷\n**遗迹工程导论**课程的授课教师，是一位**年轻女性**。她的教学风格**极度严苛**，对学生的课程表现要求极高，几乎没有通融余地。尽管学生们对她又敬又畏，但她的教学效果在学院中首屈一指。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "张婷", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-02503ac40893", "title": "学院引导人制度", "type": "概念", "aliases": [], "tags": [], "summary": "学院设有引导人制度，由资深学生或教职工担任。引导人负责接待新生、交接认证晶体、介绍学院规则等。唐辉是已知的引导人之一，曾负责2506班部分学生的入学引导工作。", "body": "### 学院引导人制度\n学院设有**引导人**制度，由资深学生或教职工担任。引导人负责接待新生、交接**认证晶体**、介绍学院规则等。**唐辉**是已知的引导人之一，曾负责2506班部分学生的入学引导工作。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3e2ce61244f194ad", "heading": "学院引导人制度", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6f51dc21d2d8", "title": "洛星雪", "type": "人物", "aliases": ["伊维娅·希洛瓦"], "tags": [], "summary": "来自裂缝的少女，黑发紫瞳，被洛星宁捡到并抚养数年。是诞生于创生之树的少女，从这一点上，她和白羽绫可以算是母女。小小的种子最终会长成参天的大树，支撑起这一片天地。女孩早已不记得自己如何诞生，一场寻乡之旅即将开始。", "body": "### 伊维娅·希洛瓦\n> \"让一切重新转起来吧\"\r\n\r\n来自裂缝的少女，黑发紫瞳，被洛星宁捡到并抚养数年。是诞生于创生之树的少女，从这一点上，她和白羽绫可以算是母女。小小的种子最终会长成参天的大树，支撑起这一片天地。女孩早已不记得自己如何诞生，一场寻乡之旅即将开始。\r\n\r\n**人物性格：** 对待朋友真诚友善，在朋友面前会和生活中有一点笨。对待他人谦逊，有着自己的自傲。喜欢捉弄人和看嚣张的人吃瘪。可以帮助的小忙会帮助，复杂的事情懒得帮。发生应急情况会让自己冷静下来，在战争中会优先保存实力，但是会尽力保护朋友和手下的安全。\n\n### 洛星雪\n来自裂缝之少女，被洛星宁捡到并带回家悉心培养。天真，幼稚，战斗力却惊人的高。见希维娅。（与伊维娅·希洛瓦为同一人，两个不同称呼）\n\n### 洛星雪的\"印记\"\n洛星雪身上有一个特殊的**\"印记\"**，这个印记只有**辰（白羽辰）和伊瑟尔**能够看到。印记的性质、来源和含义尚未完全揭示，但它的存在暗示雪（伊维娅）身上承载着远超洛星一族认知范围的秘密。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "伊维娅·希洛瓦", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "洛星雪", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "洛星雪的\"印记\"", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-39fc699843bb"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-7054b714c598", "title": "罪西", "type": "人物", "aliases": ["孙言默"], "tags": [], "summary": "年龄：17，身高：1.90。", "body": "### 罪西（孙言默）\n年龄：17，身高：1.90。\r\n\r\n出身在一个普通家庭，做事不经过思考，喜欢帮助别人，但是却总是不顾及自己。他是一个很中二、很不按常理走的人，大多数时候很不正经。\r\n\r\n> \"看到陷入困难的人你会怎么做？我的选择似乎永远是帮助他们，可能是我会死。\"\r\n> \"我是这样的人吗？这是我看到了那个女孩子要被裂缝中的怪物咬碎时的想法。\"\r\n> \"是的吧。\"\r\n\r\n**黎与罪西的相识：** 十二岁的罪西和家人在去避难所的路上，突然出现在人群一侧的裂缝构造体让本来还算有秩序的人群瞬间乱成一团。罪西和父母被人群冲散了，他只能跑，凭着本能的跑。他躲进了一个地下室里面，一位小女孩已经躲藏在里面了，但没多久，裂缝构造体也找到了这里。\r\n\r\n要么活一个，要么全死。罪西很想做那个活下去的，但他看了看眼前这个眼泪汪汪的女孩子，在留下一句\"尽可能的活下去\"以后，他冲了出去，将构造体引走。然而一个孩子怎么可能跑得过连车都能追得上的构造体呢，仅仅是绕过两个转角，罪西的腿就被刺穿了……\r\n\r\n之后的事情，他已经不记得了，但他没死。作为早就被选定的实验人选，院长虽然无法迅速赶到，但留他一命还是简单的。死亡的气息扑面而来，代表了\"死亡\"的少女轻盈地落地，构造体被轻易地抹除了，罪西也被\"死亡\"拒之门外。\n\n### 罪西的特殊体质\n罪西的体质极为特殊——他**不能适配元素**（无法使用任何元素/魔法类能力），但却拥有**极佳的相容性**。这种体质上的矛盾源于**五年前海德纳事件**的能量冲击，那次灾难永久性地改变了罪西的身体构成。\r\n\r\n此外，罪西的身份存在诡异的空白：在官方记录中**\"外界查无此人\"**——他的个人信息无法在任何户籍或档案系统中找到。而他自己也**失去了过往的记忆**，唯一记得的是**\"罪西\"**这个称号本身，不清楚自己的真实姓名。\"孙言默\"这个身份同样充满了谜团。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "罪西（孙言默）", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "罪西的特殊体质", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-12c1369d3180", "title": "契铭", "type": "人物", "aliases": [], "tags": [], "summary": "某一个家族的少爷，开朗，善良。与墨凌似乎很早就认识。喜欢枪械。见梅莹·罗斯。", "body": "### 契铭\n某一个家族的少爷，开朗，善良。与墨凌似乎很早就认识。喜欢枪械。见梅莹·罗斯。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "契铭", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-606b4da43848", "title": "崔卿棱", "type": "人物", "aliases": ["崔卿菱"], "tags": [], "summary": "一个充满极致幻想和哲理的精神病，一个未来的包租公，有着很怪的哲理和奇奇怪怪的猜测，在一次次的接近真理的过程中陷入迷茫。在团队中担任机械工程师。", "body": "### 崔卿棱\n一个充满极致幻想和哲理的精神病，一个未来的包租公，有着很怪的哲理和奇奇怪怪的猜测，在一次次的接近真理的过程中陷入迷茫。在团队中担任机械工程师。\r\n\r\n他在一个达官贵族出生，没有自己主见，就像是傀儡。而唯一的兴趣想要理解自己世界的真相。在追随真理的过程中，发现了部分真相，陷入了绝望与迷茫，从此一蹶不振。而在进入诺斯卡尔高等学院后，遇见了罪西，在罪西一次次的\"带坏\"中，逐渐有了自己的想法，摆脱了家族，并且重拾自己的梦想。\r\n\r\n他和罪西有些地方一样——一样的被人鄙视欺负，一样的迷茫，不去面对，甚至一样的拒绝前进。\n\n### 崔卿棱与观察者\n崔卿棱实际上来自**观察者组织**。在入学前，他对世界的真相进行过独立调查，但在某个关键节点，**观察者本部强行叫停**了他的调查进程——这意味着他触及到了观察者不希望被公开的领域。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "崔卿棱", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "崔卿棱与观察者", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-615f18a18bd7", "title": "奈乐", "type": "人物", "aliases": [], "tags": [], "summary": "一个来自普通家庭的孩子，童年的时候有些社恐，害怕和别人交流。并没什么原因，只是不知道怎么开口，以至于后来越来越不知道怎么和人交流，并且开始惧怕他人。", "body": "### 奈乐\n一个来自普通家庭的孩子，童年的时候有些社恐，害怕和别人交流。并没什么原因，只是不知道怎么开口，以至于后来越来越不知道怎么和人交流，并且开始惧怕他人。\r\n\r\n但是她喜欢画画，喜欢射击。因为这些都是一个人在默默进行——在画画的时候，周围是安静的，没有人打扰，不用与人交流，自己面前的画布就是自己的世界。而射击的时候，只有着自己的声音，子弹射出枪膛的声音，子弹贯穿靶子的声音，她迷上了这一切。\r\n\r\n她也喜欢花，因为有着无数的颜色。\r\n\r\n> \"我看到了花海开满来时的路。我躺在了路的尽头，让花蔓延到我的身体，让那个世界成为花的海洋。有些东西无法被挽留，当你看到花的时候，那说明我在看着你\"\r\n>\r\n> \"那位胆小的女孩子开始独当一面，面对着她不可能战胜的人，也未曾退后。她改变了自己。那片花田的花应该开了吧，她不用迷失在花海之中了，因为，那个世界上，终于有了独属于她的花田。\"\r\n\r\n世界一族的一员，于此贯彻世界的意志。最早的目标是监视并伺机干掉雪，但因为白羽三姐妹皆在这颗星球上不宜动手，空间的波动一定会被她们注意到。结果日久生情了。\n\n### 奈乐的\"魔法期\"\n奈乐会周期性地经历一种被称为**\"魔法期\"**的生理不适状态——这不是真正的魔法，而是一种原因不明的周期性体质反应，发作时伴随身体不适和情绪波动。喝**红糖水**可以一定程度缓解症状。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "奈乐", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "奈乐的\"魔法期\"", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-edbfe5863141", "title": "星雨", "type": "人物", "aliases": [], "tags": [], "summary": "其实就是星本人，唯一的差别就是力量不多。夏菲在知道星雨死了只是回到本体的情况下在学院篇杀死了星雨。对夏菲和希娜真的有感情了。对罪西，她只想罪西疯掉，所有友情与爱情都是装的。在之后复活，不再干扰计划进行，偶尔会帮夏菲和希娜的忙。", "body": "### 星雨\n> \"不过是虚妄之物，怎敢忤逆星空的意志！\"\r\n\r\n其实就是星本人，唯一的差别就是力量不多。夏菲在知道星雨死了只是回到本体的情况下在学院篇杀死了星雨。对夏菲和希娜真的有感情了。对罪西，她只想罪西疯掉，所有友情与爱情都是装的。在之后复活，不再干扰计划进行，偶尔会帮夏菲和希娜的忙。\r\n\r\n### 星雨的现世身份\r\n\r\n星雨在现在的身份是一个游走在危险边缘的**情报贩子**。她会出现在很多很危险的地方收集情报，和很多危险的人打交道买卖情报以维持生活。她已经没有家了，但她不希望别人知道这一点。\r\n\r\n星雨的本体——\"星\"——是一个位格很高的神明。星雨只是神明\"星\"的一个化身，她来这里有其他目的。雪目前不知道这些。另外，星雨不会回答\"后悔\"。\n\n### 星雨——能力具体表现\n星雨的身体能力远超常人，在战斗中表现为两个核心特征：\r\n\r\n- **瞳色变化**：正常状态下瞳色为清澈的苍蓝色；进入战斗或能力激增时，瞳色会转为**浑浊的紫红色**。\r\n- **\"错位\"闪避**：星雨的身体能在攻击命中前产生一种\"错位\"效果——攻击看似触及她的身体，但实际上打中的只是她\"曾经所在的位置\"。这是一种近乎本能的空间偏移能力。\r\n- **耐力超常**：她的身体耐力远远超出同级别学生的水平，长时间高强度作战几乎看不出疲惫。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "星雨", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "星雨——能力具体表现", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-25ae6c7715f3", "title": "海德纳·黎", "type": "人物", "aliases": [], "tags": [], "summary": "她是一个很普通的女孩子，犯了错会无措的站在那里，开心时会笑，伤心时会哭。一切都很普通，但是在他的眼中，似乎她永远都像是在阳光下开着的花，就算是光芒万丈也都黯然失色。每一次的失败都不会放弃，她没有什么特别的性格，一切都是刚刚好的样子。", "body": "### 海德纳·黎\n> [你再怎么想她，也只是在梦中手足无措的看着她在那里站着，而她不是走向你]\r\n\r\n她是一个很普通的女孩子，犯了错会无措的站在那里，开心时会笑，伤心时会哭。一切都很普通，但是在他的眼中，似乎她永远都像是在阳光下开着的花，就算是光芒万丈也都黯然失色。每一次的失败都不会放弃，她没有什么特别的性格，一切都是刚刚好的样子。\r\n\r\n**核心对话1：**\r\n- \"你怎么在这？好久不见啊\"\r\n- \"你也是他们中的一员啊...嗯，是很久不见了\"\r\n- \"这几年过去，看起来你变了很多啊\"\r\n- \"可能，是吧\"\r\n\r\n**核心对话2：**\r\n- \"你还是拒绝了，可以有一个理由吗？\"\r\n- \"抱歉\"\r\n- \"我还是输了，无论是这里，还是那个地方的我。至少至此我没有站在那里了吧\"\n\n### 海德纳·黎——现任家主\n黎在父亲战死后继任为**海德纳一族的现任家主**。尽管外表看似普通、温柔的女孩子，但她实际上承担着整个家族的领导和决策责任。这份责任和她温柔的个性形成了鲜明的反差。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "海德纳·黎", "role": "摘录来源"}, {"documentId": "b41a0582c58c745d", "heading": "海德纳·黎——现任家主", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-3b339febf98c", "title": "白柔", "type": "人物", "aliases": [], "tags": [], "summary": "一个普通出身的孩子，在某一个遗迹开启时不幸进入，被在废墟开拓的银发现。在废墟内因为意外失去了部分记忆——白柔是失忆的人，对自己的过去认知极其模糊。她只知道\"自己是被银从危险的遗迹中救出来的孩子，是银的助手与学生\"。她很敬重银，也很喜欢银，对银是非常感恩的。银送她进入了诺斯卡尔高等", "body": "### 白柔\n一个普通出身的孩子，在某一个遗迹开启时不幸进入，被在废墟开拓的银发现。在废墟内因为意外失去了部分记忆——白柔是**失忆的人**，对自己的过去认知极其模糊。她只知道\"自己是被银从危险的遗迹中救出来的孩子，是银的助手与学生\"。她很敬重银，也很喜欢银，对银是非常感恩的。银送她进入了诺斯卡尔高等学院，成为雪的舍友。\n\n### 白柔\n一个普通出身的孩子，在某一个遗迹开启时不幸进入，被在废墟开拓的银发现。在废墟内因为意外失去了部分记忆，银送她进入了诺斯卡尔高等学院，成为了银的助手。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "白柔", "role": "摘录来源"}, {"documentId": "aa6050924e73cd55", "heading": "白柔", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-3f50a6e1f7f1", "title": "星言小队", "type": "组织", "aliases": [], "tags": [], "summary": "星言小队全员都是男生：罪西、墨凌、崔卿菱、契铭。并且在入学前几人就认识。洛星雪（伊维娅）不是星言小队成员。", "body": "### 星言小队\n星言小队全员都是男生：罪西、墨凌、崔卿菱、契铭。并且在入学前几人就认识。洛星雪（伊维娅）不是星言小队成员。\r\n\r\n---", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "星言小队", "role": "摘录来源"}, {"documentId": "10e0c415f8dcac99", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-cb15545e5f47", "title": "洛星宁", "type": "人物", "aliases": [], "tags": [], "summary": "洛星宁（洛星雪的父亲）被确认为塔罗斯世界中\"五个人之一\"——五个知晓并参与某些世界级秘密计划的核心人物之一。他的身份和地位远不止洛星一族前任家主这么简单。具体细节尚待揭示。", "body": "### 洛星宁——\"五个人之一\"\n洛星宁（洛星雪的父亲）被确认为塔罗斯世界中**\"五个人之一\"**——五个知晓并参与某些世界级秘密计划的核心人物之一。他的身份和地位远不止洛星一族前任家主这么简单。具体细节尚待揭示。\n\n### 洛星宁\n洛星一族的前任家主，雪的父亲，为人刚正。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "洛星宁——\"五个人之一\"", "role": "摘录来源"}, {"documentId": "3b0b42e9fdba7fff", "heading": "洛星宁", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-f70ec14071eb", "title": "海德纳·斯诺", "type": "人物", "aliases": [], "tags": [], "summary": "海德纳·黎的二叔，棕色头发中掺着灰白，性格开朗豪爽，与黎父亲的严肃威严截然不同。他的左手无名指上戴着一枚纹章戒指，这是海德纳家族核心成员的身份象征。斯诺在黎继任家主后承担着辅佐和支持的角色。", "body": "### 海德纳·斯诺\n海德纳·黎的**二叔**，棕色头发中掺着灰白，性格**开朗豪爽**，与黎父亲的严肃威严截然不同。他的**左手无名指上戴着一枚纹章戒指**，这是海德纳家族核心成员的身份象征。斯诺在黎继任家主后承担着辅佐和支持的角色。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "b41a0582c58c745d", "heading": "海德纳·斯诺", "role": "摘录来源"}, {"documentId": "49dc0f9f0ed01ceb", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-39fc699843bb", "title": "洛星一族", "type": "组织", "aliases": [], "tags": [], "summary": "古老的家族，但是随着世界的变化日渐衰弱，依靠着其他影子的帮助勉强续命。但雪是个例外，这是个注定备受关注的孩子，即使这关注不是来源于普通人的。", "body": "### 洛星一族\n古老的家族，但是随着世界的变化日渐衰弱，依靠着其他影子的帮助勉强续命。但雪是个例外，这是个注定备受关注的孩子，即使这关注不是来源于普通人的。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3b0b42e9fdba7fff", "heading": "洛星一族", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "49579dc47a410583", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-b9b1735746d0", "title": "洛星一族的预言", "type": "概念", "aliases": [], "tags": [], "summary": "洛星一族起源于伯斯塔遗迹。最早的洛星一族发现并掌握了遗迹中的折跃技术，以此成为可以威慑其他影子保护自己族群的影子一族。而在那之前，洛星一族实际上已经存在数个纪元。", "body": "### 洛星一族的预言\n洛星一族起源于伯斯塔遗迹。最早的洛星一族发现并掌握了遗迹中的折跃技术，以此成为可以威慑其他影子保护自己族群的影子一族。而在那之前，洛星一族实际上已经存在数个纪元。\r\n\r\n他们起源于一个预言：\r\n\r\n> 在钟的第二次敲击之后，洁白的十字星会自天空落下，她会在始源之人的教导下寻找自身的洁净，在星空的引导下与高塔、迷雾与世界一同前行，行经三大节点，构造出现象之树，穿过纯洁者的封锁，并完成第十一质点与第二十三条路径的证明，最终抵达王国的流溢。\r\n\r\n洛星这一姓氏，便是源于预言中的十字星自天空落下。这条预言的来源已经无从考证，只知道这是洛星一族最重要的秘辛与所有家主都在准备与等候的信条。直到伊维娅降临，洛星宁作为现任家主，等到了预言中的十字星。\r\n\r\n### 预言的真实含义\r\n\r\n预言实际上来源于**希尔德斯**，也就是钟的证明者，世界的大预言家。他预见到了\"王女\"的存在——一个被至高之人彻底封锁的存在，连提到她的名字都会被立刻诛杀。希尔德斯预见到了在终末的未来，永恒的回归中只剩王女的身影，并向他传达了找到她的指令。\r\n\r\n希尔德斯预见到了王女会在遥远的将来于塔罗斯遇见一个\"被命线缠绕之物\"，他将预言留在了此地。\r\n\r\n预言的真实对应是：在命定的第二个影子被袭击之后，伊维娅会从裂缝中降生；她会在白羽绫的教导下逐渐认清自己的能力与身份；在星雨的干涉下与黎、白柔、奈乐一同前行；并在完成魔导会与观察者一之后见到降临的星空之树；在教会与白羽一族之后见到降临的水晶之树；在观察者二与魔导会二之后见到降临的裂空之树；并通过三树将未知域中的现象之树拉入塔罗斯；穿过白羽一族的谎言，重塑整合塔罗斯的原生力量，完成救世，最终成神。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3b0b42e9fdba7fff", "heading": "洛星一族的预言", "role": "摘录来源"}, {"documentId": "004617374457598c", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-cea1b2f53baf", "title": "伯斯塔城事件", "type": "事件", "aliases": [], "tags": [], "summary": "入学前约一个月，洛星一族的核心地区——伯斯塔城被卷进了一个相当复杂的事件：", "body": "### 伯斯塔城事件\n入学前约一个月，洛星一族的核心地区——伯斯塔城被卷进了一个相当复杂的事件：\r\n\r\n- 裂缝的异象突然爆发在了伯斯塔城。\r\n- 有人借着灾难想要刺杀雪和宁（洛星宁）。\r\n- 刺杀者打不过雪。\r\n- 宁则被当时正在洛星一族暂住的旅人**伊莉雅斯**救下。\r\n\r\n这件事情传播极其广泛，大部分人都已经知道了。对于外界，雪大概会说明灾后重建的情况并表达没什么大问题。但学院明确不插手外部事务，伯斯塔事件也与学院无关。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3b0b42e9fdba7fff", "heading": "伯斯塔城事件", "role": "摘录来源"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-68aba95e3f0f", "title": "王庆国", "type": "人物", "aliases": [], "tags": [], "summary": "洛星一族的管家。", "body": "### 王庆国\n洛星一族的管家。\r\n\r\n---", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3b0b42e9fdba7fff", "heading": "王庆国", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-fc2ee58f3d26", "title": "圣遗物", "type": "概念", "aliases": [], "tags": [], "summary": "洛星一族拥有一件名为\"圣遗物\"的珍贵宝物。这件宝物的具体形态和功能尚未完全揭示，但已被日亚一族觊觎数代，双方围绕圣遗物的暗中角力从未停止。圣遗物与洛星一族的预言和家族使命密切相关。", "body": "### 圣遗物\n洛星一族拥有一件名为**\"圣遗物\"**的珍贵宝物。这件宝物的具体形态和功能尚未完全揭示，但已被**日亚一族觊觎数代**，双方围绕圣遗物的暗中角力从未停止。圣遗物与洛星一族的预言和家族使命密切相关。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "3b0b42e9fdba7fff", "heading": "圣遗物", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "f33783cc0d4003c2", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "59651c6043efac22", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-421d6f82725f", "title": "夸特集团", "type": "组织", "aliases": ["K.U.A.T集团", "夸特"], "tags": [], "summary": "白羽一族下辖执行集团：核心夸特具有完整主权，地方夸特嵌入辖区外文明。", "body": "# 夸特集团\n\nK.U.A.T集团是白羽一族下辖执行集团，由 K.U.A.T Administration 直接领导，是对所有产业保持垄断、由下辖集团进行全产业产出的巨大复合体。\n\nK = Knowledge；U = Understanding；A = Application；T = Transform。\n\n## 核心与地方\n\n核心夸特承担最高政府职能，统筹规划星区内部发展，具有完整主权。\n\n地方夸特指嵌入文明内部、但文明本身不在核心夸特辖区内的集团。嵌入对象大多为处于星际时代早期以前的文明。在文明具有跨星系航行能力后，地方夸特与本地文明政府协商，选择撤离或纳入核心夸特辖区。\n\nCenter K.U.A.T Administration 对所有地方 K.U.A.T Administration 具有最高指挥权，但地方 Administration 大部分时候高度自治。\n\n选择并入核心辖区后，地方 Administration 适度参与协调地方政治，尽量不干涉内政。地方夸特的其余资本集团直接纳入整个辖区的集团管理体系，受到该集团上级与地方 Administration 共同指挥。\n\n## 下辖集团\n\n本次作者列举以下 13 个集团：\n\n- K.U.A.T军事工业集团\n- K.U.A.T食品工业集团\n- K.U.A.T能源集团\n- K.U.A.T航天工业集团\n- K.U.A.T生物制药集团\n- K.U.A.T信息科技集团\n- K.U.A.T电子重工集团\n- K.U.A.T纺织轻工业集团\n- K.U.A.T化学工业集团\n- K.U.A.T建筑工程集团\n- K.U.A.T教育培养集团\n- K.U.A.T联合科技集团\n- K.U.A.T文化互娱集团\n\n## 内部级别\n\n以下依作者给出的顺序列出。Infinite、Orange、White 为同级最高权限，分别对应不同身份类别，不解释为三个上下级。\n\n| 标识 | 别称 | 中文级别 | 部分成员与说明 |\n| --- | --- | --- | --- |\n| Infinite | — | 最高 | 具有最高级别身份权限，但不属于创始人和白羽一族 |\n| Orange | Origin | 创始 | 夸特的两位创始人，与最高、白羽同级 |\n| White | Shiro | 白羽 | 来自白羽一族的人，与最高、创始同级 |\n| Purple | Kuat | 直属 | 直接听命于创始人，不受议会管辖 |\n| Darkblue | Cabinet | 议会 | K.U.A.T Administration 成员，议员与议长 |\n| Red | Alpha | 红级 | 各集团最高管理员、部分军事将领、部分高级别管理层、监察组组长 |\n| Blue | Beta | 蓝级 | 中层管理与执行者、大部分正式成员、各执行小队 |\n| Cyan | Tech | 青级 | 技术人员、研究小组、大部分科研成员 |\n| Green | Gamma | 绿级 | 处于观察期的新成员、部分较为底层的成员 |\n| Grey | Omega | 灰级 | 来访人员 |\n\n## 组织视觉与软件映射\n\n组织印象色为黑色和青色，气质为未来感、冰冷。作者原句结尾为“未来感和冰冷干”，末字未补全，不据此扩写新的设定。\n\n现实中的 Project K.U.A.T 软件在世界内的定位是“夸特集团内部工作平台”，与组织本身的 LOGO 有区别。身份认证、工作发布等属于这一定位的背景，当前不实现；以后可能以象征性美化动画体现。\n\n来源：白羽奈绪于 2026-10-04 的直接补充。旧资料保留为历史版本；本次列举取代旧“11个集团”的数量说明。\r\n", "notes": "以2026-10-04作者补充为准，列举13个集团。Infinite、Orange、White同级。旧资料仅供历史核对。", "status": "已确认", "visibility": "内部", "sources": [{"documentId": "8215499c20c37a95", "heading": "夸特集团", "role": "作者最新确认"}, {"documentId": "aa6050924e73cd55", "heading": "夸特（K.U.A.T集团）", "role": "摘录来源"}, {"documentId": "8215499c20c37a95", "heading": "夸特集团", "role": "摘录来源"}], "related": ["entry-aa41864a5013"], "updatedAt": null, "pendingSync": false, "revision": 0, "seedRevision": "kuat-20261004"}, {"id": "entry-7ec542fdc38a", "title": "梅莹一族", "type": "组织", "aliases": [], "tags": [], "summary": "掌握着这个世界的宏观经济走向，但是从来不去操控走向，只是在经济崩盘的时候出现，将一切恢复原样。", "body": "### 梅莹一族\n掌握着这个世界的宏观经济走向，但是从来不去操控走向，只是在经济崩盘的时候出现，将一切恢复原样。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "梅莹一族", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "10d996b4d25f80c7", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-6f0a3280ab24", "title": "梅莹·罗斯", "type": "人物", "aliases": [], "tags": [], "summary": "身份背景：现任家主。", "body": "### 梅莹·罗斯\n身份背景：现任家主。\r\n\r\n人物性格：笑里藏刀，唯利是图，混沌中立，沉思熟虑。不会将任何把柄落入他人手中，尽量不去牵连无辜，不会去欺凌弱小。明明曾经如此的人，一个阴暗的捕猎者，却在哥哥死后变为了自己曾经最嫌弃的样子。是在模仿吗？是怀念，是懊悔，是所有。\r\n\r\n> 一个人的死足以改变世界吗？\r\n> 一个人的死的确不会改变世界，一个人的死改变的是要改变这个世界的人。\r\n> 他的一生就此消逝，为自己的心中所念。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "梅莹·罗斯", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-c8d2563447dc", "title": "梅莹·翎", "type": "人物", "aliases": [], "tags": [], "summary": "身份背景：前任家主预选人。人物性格：精明，善良，隐忍，永远不会丧失希望，向往故事与经历。", "body": "### 梅莹·翎\n身份背景：前任家主预选人。人物性格：精明，善良，隐忍，永远不会丧失希望，向往故事与经历。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "梅莹·翎", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-2f0f10fabe92", "title": "莱拉", "type": "人物", "aliases": ["AI管理员"], "tags": [], "summary": "图书馆的AI管理员，与白羽辰和伊迪娅的关系非常要好。", "body": "### 莱拉（AI管理员）\n图书馆的AI管理员，与白羽辰和伊迪娅的关系非常要好。\r\n\r\n**核心对话1：**\r\n- \"你就这么把那本书借出去了吗。\"\r\n- \"当然了，我这里可是图书馆，不借书干嘛。\"\r\n- \"那本书记载着多少古文明的东西呢，借给那些没有权限的人真的好吗\"\r\n- \"放心啦，他们看不懂多少的，而且只能借一次，不超过十二个系统时\"\r\n- \"现在还有多久。\"\r\n- \"七个系统时，到时候他们必须来还。\"\r\n- \"好吧。\"\r\n\r\n**核心对话2：**\r\n- \"有书籍被盗，执行找回协议，出动自律机器。\"\r\n- \"那帮人果然还是不老实啊。\"\r\n- \"他们既然向图书馆宣战了，那就让他们感受一下泰伦文明的真正实力。\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "莱拉（AI管理员）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": ["entry-02cafd367478"], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-86ae75a882d3", "title": "伊迪娅", "type": "人物", "aliases": ["伊迪亚"], "tags": [], "summary": "超古代遗迹的研究者，来自天外的旅人，与白羽三姐妹有相当亲密的关系。天然呆，很可爱。偶尔也会被白羽三姐妹拜托处理一些不能由白羽一族直接下场处理的事件。", "body": "### 伊迪娅（idea）\n超古代遗迹的研究者，来自天外的旅人，与白羽三姐妹有相当亲密的关系。天然呆，很可爱。偶尔也会被白羽三姐妹拜托处理一些不能由白羽一族直接下场处理的事件。\r\n\r\n诞生自幻想的少女，也对万物报以幻想。有着能够以意志控制世界的能力，绫把这能力形容为——诞生自少女的物质最终回应了少女的愿望。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "伊迪娅（idea）", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-ac12fd14d7ad", "title": "伊莉雅斯", "type": "人物", "aliases": [], "tags": [], "summary": "与伊迪娅同行的护卫，是伊迪娅非常要好的朋友。", "body": "### 伊莉雅斯\n与伊迪娅同行的护卫，是伊迪娅非常要好的朋友。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "伊莉雅斯", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "ce923a5d1293500b", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "016482ec1ba43ca8", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "9568edd41207c91c", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-06967cdeb6c3", "title": "希尔德斯", "type": "人物", "aliases": [], "tags": [], "summary": "来自宇宙另一面的守护者，钟的证明者。", "body": "### 希尔德斯\n来自宇宙另一面的守护者，钟的证明者。\r\n\r\n**核心独白1：**\r\n- \"那个人类，居然真的敲响了钟。\"\r\n- \"尽管自己并不自知。\"\r\n- \"钟的变化很快就会被尽数观测。\"\r\n- \"论证已然结束。\"\r\n- \"该动身了。\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "希尔德斯", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-7a22812623ab", "title": "被囚禁的王女", "type": "人物", "aliases": [], "tags": [], "summary": "被囚禁于遗忘之地的王女殿下，从遥远的过去一直存在的——", "body": "### ？？？（被囚禁的王女）\n被囚禁于遗忘之地的王女殿下，从遥远的过去一直存在的——\r\n\r\n- \"你看得见吾辈吗？\"\r\n- \"看得见。\"\r\n- \"有趣，告诉吾你的名字。\"\r\n- \"洛星雪。\"\r\n- \"嗯？啊，吾看到了。\"\r\n- \"请问你到底是……\"", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "？？？（被囚禁的王女）", "role": "摘录来源"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-450e8ffb5f94", "title": "银的研究院", "type": "组织", "aliases": [], "tags": [], "summary": "兼具智慧、平等、宠爱、独立于一身的人，不畏惧任何困难。很在乎几个自己培养起来的孩子，将她们视如己出，对孩子们甚至可以说是溺爱。银本身并非影子之一，但因为自身的强大和伊瑟尔的支持，她在影子中的行动极其自由且力量强大。但她几乎从不在影子中出现。", "body": "### 银的研究院\n### 银\r\n\r\n兼具智慧、平等、宠爱、独立于一身的人，不畏惧任何困难。很在乎几个自己培养起来的孩子，将她们视如己出，对孩子们甚至可以说是溺爱。银本身并非影子之一，但因为自身的强大和伊瑟尔的支持，她在影子中的行动极其自由且力量强大。但她几乎从不在影子中出现。\r\n\r\n### 白柔\r\n\r\n一个普通出身的孩子，在某一个遗迹开启时不幸进入，被在废墟开拓的银发现。在废墟内因为意外失去了部分记忆，银送她进入了诺斯卡尔高等学院，成为了银的助手。\r\n\r\n### 科尔斯\r\n\r\n一个对裂缝有着痴迷狂热的男孩，对裂缝的研究非常积极，甚至通过超乎常人的联想能力推断出了时空异位的存在。银看重他的研究能力，将其收入研究所。数年如一日的观测着裂缝的数据。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "银的研究院", "role": "摘录来源"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}, {"id": "entry-cf1408574806", "title": "科尔斯", "type": "人物", "aliases": [], "tags": [], "summary": "一个对裂缝有着痴迷狂热的男孩，对裂缝的研究非常积极，甚至通过超乎常人的联想能力推断出了时空异位的存在。银看重他的研究能力，将其收入研究所。数年如一日的观测着裂缝的数据。", "body": "### 科尔斯\n一个对裂缝有着痴迷狂热的男孩，对裂缝的研究非常积极，甚至通过超乎常人的联想能力推断出了时空异位的存在。银看重他的研究能力，将其收入研究所。数年如一日的观测着裂缝的数据。", "notes": "由原始设定拆分，尚未逐条统一历史版本。参考资料中的讨论与推测不自动构成定稿。", "status": "待核对", "visibility": "内部", "sources": [{"documentId": "aa6050924e73cd55", "heading": "科尔斯", "role": "摘录来源"}, {"documentId": "6841b34874060b53", "heading": "", "role": "相关讨论／版本参考"}, {"documentId": "4a13ff923d416989", "heading": "", "role": "相关讨论／版本参考"}], "related": [], "updatedAt": null, "pendingSync": false, "revision": 0}]};
